window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[267]={"id":"267","numero":267,"titre":"Troubles de l'équilibre acido-basique et désordres hydro-électrolytiques","objectifs":[{"id":"267-1","rang":"A","rubrique":"Définition","titre":"Connaître les indications de prescription et les seuils de définitions de la sévérité d’une hyponatrémie","contenu":"<p>L'<span class=\"kw-def\"><strong>hyponatrémie</strong></span> traduit toujours un <span class=\"kw-def\">excès d'eau</span> (hyperhydratation intracellulaire), et non un manque primitif de sodium. Elle s'accompagne d'une <span class=\"kw-bio\">hypo-osmolalité plasmatique</span>.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Seuil</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Natrémie</strong></span></td><td>hyponatrémie si <span class=\"kw-chiffre\">&lt; 135 mmol/L</span> · <span class=\"kw-alerte\">sévère si &lt; 120 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Osmolalité plasmatique</strong></span></td><td>diminuée : <span class=\"kw-chiffre\">Posm &lt; 280 mOsm/kg</span> <span class=\"kw-def\">(formule : [Na⁺ × 2] + glycémie en mmol/L)</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Gravité = symptômes</strong></span></td><td>la sévérité se juge sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes neurologiques</span> (modérés <span class=\"kw-bio\">vs</span> sévères), pas seulement sur le chiffre</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Avant de conclure, éliminer une fausse hyponatrémie</strong> (osmolalité plasmatique mesurée normale ou élevée) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Contexte · mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Hyponatrémie factice</strong></span></td><td><span class=\"kw-etio\">hyperprotidémie (myélome)</span>, <span class=\"kw-etio\">hyperlipidémie</span> → la phase aqueuse du plasma diminue ; <span class=\"kw-bio\">osmolalité normale</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Pseudo-hyponatrémie</strong></span></td><td><span class=\"kw-etio\">hyperglycémie</span>, méthanol/éthanol → transfert d'eau ; <span class=\"kw-alerte\">hyperosmolalité plasmatique</span> ; <span class=\"kw-bio\">natrémie</span> corrigée de <span class=\"kw-def\">Katz</span> : [Na] + 0,3 × (<span class=\"kw-bio\">glycémie</span> − 5)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Hyponatrémie <span class=\"kw-chiffre\">&lt; 135</span>, sévère <span class=\"kw-chiffre\">&lt; 120</span>, toujours hypo-osmolaire (<span class=\"kw-chiffre\">&lt; 280 mOsm/kg</span>). Une <span class=\"kw-bio\">natrémie</span> basse avec osmolalité normale/haute = fausse ou pseudo-hyponatrémie, à ne pas corriger comme une vraie.</div>","frequence":0},{"id":"267-2","rang":"B","rubrique":"Éléments physiopathologiques","titre":"Comprendre les mécanismes de l’hyponatrémie","contenu":"<p>Un <span class=\"kw-def\">bilan hydrique positif</span> abaisse l'osmolalité extracellulaire → l'eau migre vers le secteur <span class=\"kw-clinique\">intracellulaire</span> → nouvel équilibre à osmolalité basse = <span class=\"kw-def\"><strong>hyperhydratation intracellulaire</strong></span>.</p>\n      <p>La capacité d'excrétion d'eau libre du rein est normalement énorme ; elle dépend de la <span class=\"kw-def\">suppression de l'ADH</span> et du pouvoir de <span class=\"kw-def\">dilution maximal</span> (osmolalité urinaire minimale <span class=\"kw-chiffre\">60 mOsm/kg</span> — il faut un minimum d'osmoles pour éliminer de l'eau).</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Situations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Apport d'eau dépassant les capacités</strong></span></td><td><span class=\"kw-etio\">potomanie</span> ; <span class=\"kw-etio\">buveurs de bière</span> ; syndrome <span class=\"kw-etio\">« Tea and Toast »</span> (apport osmolaire faible)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Pouvoir de dilution altéré</strong></span></td><td><span class=\"kw-etio\">insuffisance rénale</span> ; <span class=\"kw-ttt\">diurétiques thiazidiques</span> ; <span class=\"kw-bio\">hypersécrétion d'ADH</span></td></tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>ADH inappropriée vs appropriée</strong></span></td>\n            <td>\n              <strong>Inappropriée :</strong> <span class=\"kw-etio\">SIADH</span> (volémie normale)<br>\n              <strong>Appropriée (hypovolémie) :</strong> hypovolémie <span class=\"kw-clinique\">vraie</span> (DEC) ou <span class=\"kw-clinique\">efficace</span> (<span class=\"kw-ci\">insuffisance cardiaque</span>, cirrhose, <span class=\"kw-clinique\">syndrome néphrotique</span>)<br>\n              <strong>Seuil bas :</strong> reset osmostat (<span class=\"kw-etio\">grossesse</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout success\"><strong>À comprendre.</strong> L'hyponatrémie est un problème d'<span class=\"kw-def\">eau en excès</span>, pas de sel manquant. Le rein ne peut pas la corriger soit parce qu'on dépasse sa capacité de dilution (apports massifs), soit parce que l'<span class=\"kw-bio\">ADH</span> est anormalement élevée (SIADH ou stimulus volémique).</div>","frequence":3},{"id":"267-3","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les symptômes de gravité de l’hyponatrémie","contenu":"<p>La gravité tient au <span class=\"kw-def\">gonflement cellulaire</span> : l'eau gagne le secteur <span class=\"kw-clinique\">intracellulaire</span> → <span class=\"kw-clinique\">les</span> cellules gonflent → <span class=\"kw-alerte\">œdème cérébral</span> dans une <span class=\"kw-clinique\">boîte crânienne inextensible</span> → <span class=\"kw-alerte\">HTIC</span>.</p>\n      <table >\n        <thead><tr><th>Sévérité</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Modérée</strong></span></td><td><span class=\"kw-clinique\">céphalées</span> · <span class=\"kw-clinique\">confusion</span> · <span class=\"kw-clinique\">nausées</span> (sans <span class=\"kw-clinique\">vomissements</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Sévère</strong></span></td><td><span class=\"kw-clinique\">vomissements</span> · <span class=\"kw-alerte\">comitialité</span> · <span class=\"kw-clinique\">détresse cardio-respiratoire</span> · <span class=\"kw-clinique\">somnolence</span> · <span class=\"kw-alerte\">coma (Glasgow ≤ 8)</span> → <span class=\"kw-alerte\">décès</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le risque est majeur dans l'hyponatrémie <span class=\"kw-clinique\">aiguë</span> (installation rapide, pas d'adaptation cérébrale), et pour une <span class=\"kw-bio\">natrémie</span> <span class=\"kw-chiffre\">&lt; 120 mmol/L</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une hyponatrémie symptomatique sévère (<span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-alerte\">convulsions</span>, troubles de conscience) impose une prise en charge en <span class=\"kw-alerte\">unité de soins intensifs</span> et un soluté <span class=\"kw-ttt\">NaCl hypertonique 3 %</span> — sans attendre, mais sans corriger trop vite.</div>","frequence":0},{"id":"267-4","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hyponatrémies","contenu":"<p>La démarche s'appuie sur deux temps : l'<span class=\"kw-bio\">osmolalité urinaire</span> puis l'évaluation du <span class=\"kw-def\">volume extracellulaire (VEC)</span>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Uosm ≤ 100 mOsm/kg</strong></span> (dilution adaptée)</td><td>déséquilibre des seuls apports : <span class=\"kw-etio\">potomanie</span>, <span class=\"kw-etio\">buveurs de bière</span>, <span class=\"kw-etio\">« Tea and Toast »</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Uosm &gt; 100 mOsm/kg</strong></span> (inadaptée)</td><td>évaluer le compartiment extracellulaire ↓</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>VEC</th><th>Étiologies · natriurèse</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>DEC</strong></span> (hypovolémie vraie)</td>\n            <td><strong>NaU <span class=\"kw-chiffre\">≤ 30</span> :</strong> pertes <span class=\"kw-etio\">extra-rénales</span> (digestives, cutanées, 3ᵉ secteur)<br><strong>NaU &gt; 30 :</strong> pertes rénales — <span class=\"kw-etio\">diurétiques</span>, <span class=\"kw-etio\">insuffisance surrénale</span>, cerebral salt wasting</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Euvolémie</strong></span> (excès d'eau pur)</td>\n            <td>NaU &gt; 30 : <span class=\"kw-etio\">SIADH</span> (le plus fréquent), <span class=\"kw-etio\">hypothyroïdie</span>, <span class=\"kw-etio\">hypocortisolisme</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>HEC</strong></span> (hypovolémie efficace)</td>\n            <td><span class=\"kw-clinique\">NaU basse</span> (SRAA actif) : <span class=\"kw-etio\">insuffisance cardiaque</span>, <span class=\"kw-etio\">cirrhose</span>, <span class=\"kw-etio\">syndrome néphrotique</span> ; ou <span class=\"kw-etio\">IRC avancée</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>SIADH</strong> — diagnostic d'élimination (après hypothyroïdie et hypocortisolisme exclus) ; critères : <span class=\"kw-chiffre\">Posm &lt; 275</span>, <span class=\"kw-chiffre\">Uosm &gt; 100</span>, <span class=\"kw-chiffre\">UNa &gt; 30 mmol/L</span>, <span class=\"kw-bio\">uricémie &lt; 240 µmol/L</span>, <span class=\"kw-clinique\">euvolémie</span>. Causes : <span class=\"kw-etio\">atteintes SNC</span>, <span class=\"kw-etio\">pneumopathies</span>, <span class=\"kw-etio\">médicaments (carbamazépine, ISRS, émétisants)</span>, <span class=\"kw-etio\">sécrétion ectopique (carcinome bronchique — Schwartz-Bartter)</span>.</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant une vraie hyponatrémie : (1) Uosm — apports purs si <span class=\"kw-chiffre\">≤ 100</span> ; (2) sinon VEC — DEC, euvolémie (SIADH ++), ou HEC. Chez le sujet âgé, plusieurs causes se cumulent souvent (IR + IC + <span class=\"kw-ttt\">diurétiques</span> + apports protéiques bas).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 245 — Insuffisance surrénale · 243 — Hypothyroïdie · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 279 — Cirrhose</em></p>","frequence":10,"liens":[{"href":"https://radiopaedia.org/articles/syndrome-of-inappropriate-antidiuretic-hormone-secretion","label":"Radiopaedia : SIADH"}]},{"id":"267-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des hyponatrémies en fonction de la sévérité des symptômes","contenu":"<p>Deux logiques se superposent : corriger selon le <span class=\"kw-clinique\">degré d'urgence (symptômes)</span> et traiter selon l'<span class=\"kw-def\">état du secteur extracellulaire</span>. Estimation de l'excès d'eau : <span class=\"kw-chiffre\">60 % × poids × [(natrémie/140) − 1]</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Dans tous les cas</strong></span></td><td><span class=\"kw-ttt\">restriction hydrique (500 mL/j)</span> ; limiter <span class=\"kw-clinique\">les</span> solutés hypotoniques (<span class=\"kw-ci\">G5 %</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Sévère (&lt; 120, symptomatique)</strong></span></td><td><span class=\"kw-alerte\">USI</span> : <span class=\"kw-ttt\">NaCl hypertonique 3 %</span> pour <span class=\"kw-chiffre\">+ 5 mmol/L</span> initiaux, puis relais <span class=\"kw-ttt\">NaCl 0,9 %</span> jusqu'à<span class=\"kw-chiffre\"> 130 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>DEC associée</strong></span></td><td><span class=\"kw-ttt\">NaCl isotonique 9 ‰</span> (freine la stimulation volémique de l'ADH) ; solutés balancés si acidose</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Euvolémie (SIADH)</strong></span></td><td>restriction hydrique ; si insuffisant : <span class=\"kw-ttt\">urée per os</span> ou <span class=\"kw-ttt\">furosémide + sel</span> ; échec chronique : <span class=\"kw-ttt\">tolvaptan</span> (antagoniste V2)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>HEC associée</strong></span></td><td>régime <span class=\"kw-ttt\">désodé (&lt; 2-4 g/24h)</span> + <span class=\"kw-ttt\">diurétiques de l'anse</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Vitesse de correction.</strong> Ne pas dépasser <span class=\"kw-chiffre\">10 mmol/L / 24 h</span> (puis &lt;<span class=\"kw-chiffre\"> 8 mmol/L</span> <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 h</span> suivantes) sous peine de <span class=\"kw-alerte\">myélinolyse centro-pontine</span>. Corriger toujours une <span class=\"kw-def\">hypokaliémie</span> associée (l'apport de KCl accélère la remontée de la <span class=\"kw-bio\">natrémie</span>).</div>","frequence":3},{"id":"267-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître le principal risque de la correction rapide des hyponatrémies","contenu":"<p>Le risque majeur est la <span class=\"kw-def\"><strong>myélinolyse centro-pontine</strong></span> (démyélinisation osmotique) — rare mais redoutable.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>Facteurs favorisants</strong></span></td><td>hyponatrémie <span class=\"kw-clinique\">chronique</span> corrigée trop vite (<span class=\"kw-chiffre\">&gt; 10 mmol/L / 24 h</span>) ; <span class=\"kw-def\">terrain</span> : <span class=\"kw-etio\">hypoxie, malnutrition, éthylisme, hypokaliémie</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Manifestations</strong></span></td><td><span class=\"kw-alerte\">locked-in syndrome</span> : tétraparésie spastique, diplégie faciale, paralysie oculomotrice (verticalité préservée) ; <span class=\"kw-clinique\">pas de trouble de vigilance</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Imagerie</strong></span></td><td><span class=\"kw-imagerie\">IRM</span> : <span class=\"kw-radio\">hypersignal T2 FLAIR</span> du centre du pont (protubérance)</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Traitement</strong></span></td><td><span class=\"kw-alerte\">préventif ++</span> : correction progressive ; si trop rapide → <span class=\"kw-ttt\">soluté glucosé 5 %</span> + <span class=\"kw-ttt\">desmopressine</span> pour « faire machine arrière »</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Cible de correction : <span class=\"kw-chiffre\">&lt; 10 mmol/L</span> <span class=\"kw-clinique\">les</span> 24 premières heures, puis <span class=\"kw-chiffre\">&lt; 8 mmol/L</span> les <span class=\"kw-chiffre\">24 h</span> suivantes. La MCP frappe surtout l'hyponatrémie <span class=\"kw-clinique\">chronique</span> corrigée trop vite.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/osmotic-demyelination-syndrome","label":"Radiopaedia : Osmotic demyelination syndrome"}]},{"id":"267-7","rang":"A","rubrique":"Définition","titre":"Connaître les modalités du diagnostic d’une hypernatrémie","contenu":"<p>L'<span class=\"kw-def\"><strong>hypernatrémie</strong></span> traduit un <span class=\"kw-def\">bilan hydrique négatif</span> : hyperosmolalité → l'eau quitte <span class=\"kw-clinique\">les</span> cellules → <span class=\"kw-def\">déshydratation intracellulaire (DIC)</span>.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Natrémie</strong></span></td><td><span class=\"kw-chiffre\">&gt; 145 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Osmolalité plasmatique</strong></span></td><td>élevée : <span class=\"kw-chiffre\">Posm &gt; 300 mOsm/kg</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Clinique</strong></span></td><td><span class=\"kw-clinique\">soif</span> (parfois intense) · perte de poids · <span class=\"kw-clinique\">sécheresse des muqueuses</span> (face inférieure de la langue) · syndrome <span class=\"kw-clinique\">polyuro-polydipsique</span> si cause rénale</td></tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-alerte\">hypernatrémie</span> est rare car la <span class=\"kw-clinique\">soif</span> compense la perte d'eau : elle suppose un trouble de la soif ou un trouble d'accès à l'eau. Cas à part : <span class=\"kw-def\">DIC sans hypernatrémie</span> (osmole de bas PM autre que le Na⁺ : <span class=\"kw-etio\">mannitol</span>, <span class=\"kw-etio\">éthylène glycol</span> → trou osmotique).</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Hypernatrémie = <span class=\"kw-chiffre\">Na &gt; 145</span> + <span class=\"kw-chiffre\">Posm &gt; 300</span> = <span class=\"kw-clinique\">déshydratation</span> intracellulaire. Le symptôme cardinal est la soif ; son absence (sujet âgé, nourrisson, <span class=\"kw-alerte\">coma</span>) explique la survenue du trouble.</div>","frequence":1},{"id":"267-8","rang":"B","rubrique":"Éléments physiopathologiques","titre":"Comprendre les mécanismes de l’hypernatrémie","contenu":"<p>Le bilan d'eau est normalement équilibré entre <span class=\"kw-clinique\">entrées</span> (régulées par la <span class=\"kw-clinique\">soif</span>) et <span class=\"kw-clinique\">sorties</span> rénales (régulées par l'<span class=\"kw-bio\">ADH</span>).</p>\n      <p>Un bilan d'eau négatif (<span class=\"kw-bio\">hyperosmolalité</span>, <span class=\"kw-def\">DIC</span>) survient en cas de :</p>\n      <ul>\n        <li><span class=\"kw-def\">Trouble de la soif</span> (atteinte des centres / <span class=\"kw-clinique\">osmorécepteurs hypothalamiques</span>)</li>\n        <li><span class=\"kw-clinique\">Perte d'eau extra-rénale</span> (<span class=\"kw-etio\">cutanée</span>, <span class=\"kw-etio\">respiratoire</span>)</li>\n        <li><span class=\"kw-clinique\">Perte d'eau rénale</span> par absence de sécrétion d'<span class=\"kw-bio\">ADH</span> ou de réponse rénale à l'ADH</li>\n        <li><span class=\"kw-clinique\">Trouble d'accès à l'eau</span></li>\n      </ul>\n      <p>L'<span class=\"kw-bio\">ADH</span> (noyaux para-ventriculaires et supra-optiques → posthypophyse) agit sur <span class=\"kw-clinique\">les</span> récepteurs <span class=\"kw-def\">V2</span> du canal collecteur → insertion d'<span class=\"kw-def\">aquaporine 2</span> → réabsorption d'eau (<span class=\"kw-def\">gradient cortico-papillaire</span> nécessaire). Seuil de stimulation maximale : <span class=\"kw-chiffre\">320 mOsm/kg</span>.</p>\n      <div class=\"obj-callout success\"><strong>À comprendre.</strong> Tant que la soif est intacte et l'accès à l'eau possible, l'hyperosmolalité se traduit par une <span class=\"kw-clinique\">polydipsie</span> plutôt que par une <span class=\"kw-alerte\">hypernatrémie</span>. La DIC survient quand ce garde-fou tombe.</div>","frequence":2},{"id":"267-9","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les symptômes de gravité de l’hypernatrémie","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">signes de gravité</span> de l'<span class=\"kw-def\">hypernatrémie</span> sont <span class=\"kw-clinique\">neurologiques</span>, corrélés au <span class=\"kw-clinique\">degré</span> et à la <span class=\"kw-clinique\">rapidité d'installation</span> (peu spécifiques, peu évocateurs) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre d'origine centrale</span></li>\n        <li><span class=\"kw-clinique\">Somnolence</span>, <span class=\"kw-clinique\">asthénie</span>, troubles du comportement (<span class=\"kw-clinique\">irritabilité</span>)</li>\n        <li><span class=\"kw-alerte\">Crise convulsive</span>, <span class=\"kw-alerte\">coma</span></li>\n        <li><span class=\"kw-alerte\">Hémorragies cérébro-méningées</span>, <span class=\"kw-alerte\">hématomes sous-duraux</span>, <span class=\"kw-alerte\">thromboses veineuses cérébrales</span> (par rétraction du parenchyme cérébral)</li>\n      </ul>\n      <p>Sur le plan <span class=\"kw-ttt\">biologique</span>, la gravité s'apprécie sur le chiffre de <span class=\"kw-bio\">natrémie</span> (<span class=\"kw-chiffre\">&gt; 145 mmol/L</span>) et l'<span class=\"kw-bio\">osmolalité plasmatique</span> (<span class=\"kw-chiffre\">&gt; 300 mOsm/kg</span>).</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> / piège.</strong> En miroir de l'<span class=\"kw-def\">hyponatrémie</span>, la correction <span class=\"kw-alerte\">trop rapide</span> d'une <span class=\"kw-clinique\">hypernatrémie chronique</span> expose à l'<span class=\"kw-alerte\">œdème cérébral</span> — d'où des vitesses de correction strictes (cf. traitement).</div>","frequence":0},{"id":"267-10","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hypernatrémies","contenu":"<p>Après avoir éliminé une <span class=\"kw-def\">insuffisance d'apport en eau</span>, le diagnostic repose sur l'évaluation du <span class=\"kw-def\">VEC</span> et de la diurèse.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Déficit d'apport d'eau</strong></span></td><td><span class=\"kw-etio\">hypodipsie primitive</span> (anomalie hypothalamique) ; troubles d'accès : <span class=\"kw-etio\">nourrisson, grabataire, réanimation (coma, sédation)</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Pertes extra-rénales</strong></span></td><td>urines concentrées (U/P osm &gt; 1) : <span class=\"kw-etio\">cutanées</span> (coup de chaleur, brûlure), <span class=\"kw-etio\">respiratoires</span>, <span class=\"kw-etio\">digestives</span> (<span class=\"kw-clinique\">diarrhée</span> osmotique)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Pertes rénales</strong></span></td><td><span class=\"kw-etio\">diabète insipide</span> (central / néphrogénique) ; <span class=\"kw-etio\">polyurie osmotique</span> (<span class=\"kw-etio\">diabète</span> sucré, mannitol)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Apport massif de sodium</strong></span></td><td>surtout chez l'enfant : <span class=\"kw-etio\">soluté bicarbonaté hypertonique</span>, bain de dialyse trop riche en Na</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-etio\">Diabète</span> insipide</strong> — polyurie hypotonique (<span class=\"kw-chiffre\">U/P osm &lt; 1</span>, Uosm <span class=\"kw-chiffre\">&lt; 300 mOsm/L</span>). L'épreuve de <span class=\"kw-bio\">restriction hydrique + ADH exogène (ddAVP)</span> distingue : <span class=\"kw-def\">central</span> (Uosm s'élève après ADH) de <span class=\"kw-def\">néphrogénique</span> (Uosm non modifiée par l'ADH).</p>\n      <table >\n        <thead><tr><th>DI central</th><th>DI néphrogénique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">post-trauma / chirurgie hypophysaire</span> ; ischémie (<span class=\"kw-etio\">choc, Sheehan</span>) ; néoplasie (craniopharyngiome, germinome) ; granulome (<span class=\"kw-etio\">sarcoïdose, histiocytose</span>)</td>\n            <td><span class=\"kw-etio\">médicaments (lithium, amphotéricine B, déméclocycline)</span> ; <span class=\"kw-etio\">hypercalcémie, hypokaliémie</span> ; néphropathie interstitielle ; <span class=\"kw-etio\">héréditaire</span> (récepteur ADH lié à l'X)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant un syndrome polyuro-polydipsique : d'abord éliminer une <span class=\"kw-etio\">polyurie osmotique</span> (<span class=\"kw-etio\">diabète</span>, mannitol — trou osmolaire urinaire), puis distinguer DI central <span class=\"kw-bio\">vs</span> néphrogénique par l'épreuve de restriction + ADH.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 245 — Insuffisance surrénale · 247 — <span class=\"kw-etio\">Diabète</span> · 244 — Adénome hypophysaire</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/diabetes-insipidus","label":"Radiopaedia : Diabetes insipidus"}]},{"id":"267-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des hypernatrémies","contenu":"<p>Estimation du déficit en eau : <span class=\"kw-chiffre\">60 % × poids × [(natrémie/140) − 1]</span>. La correction se fait par apport d'eau, modulé selon le secteur extracellulaire.</p>\n      <table >\n        <thead><tr><th>Voie / soluté</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\"><strong>Eau de boisson</strong></span></td><td>per os ou par SNG</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Soluté glucosé</strong></span></td><td><span class=\"kw-ttt\">G5 % ou G2,5 %</span> IV</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>NaCl hypotonique</strong></span></td><td><span class=\"kw-ttt\">NaCl 0,45 %</span> (<span class=\"kw-clinique\">déshydratation</span> globale)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>État du VEC</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">DIC isolée</span></td><td>eau de boisson PO/SNG, ou G5/G2,5 IV</td></tr>\n          <tr><td><span class=\"kw-def\">Déshydratation globale</span></td><td><span class=\"kw-ttt\">NaCl 0,45 %</span> (voire <span class=\"kw-chiffre\">0,9 %</span> si DEC sévère : corriger d'abord la volémie)</td></tr>\n          <tr><td><span class=\"kw-def\">HEC associée</span></td><td><span class=\"kw-ttt\">diurétique de l'anse</span> + eau pure (PO) ou soluté hypotonique (IV)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Deux pièges.</strong> (1) <span class=\"kw-ci\">Ne JAMAIS administrer d'eau pure IV</span> → hémolyse. (2) Vitesse de correction : DIC <span class=\"kw-clinique\">chronique</span> ↓ <span class=\"kw-bio\">natrémie</span> de <span class=\"kw-chiffre\">0,5 mmol/L/h</span> (max <span class=\"kw-chiffre\">10 mmol/L/j</span>) ; DIC <span class=\"kw-clinique\">aiguë</span> ↓ de <span class=\"kw-chiffre\">1-2 mmol/L/h</span> — sinon <span class=\"kw-alerte\">œdème cérébral</span>.</div>","frequence":0},{"id":"267-12","rang":"B","rubrique":"Éléments physiopathologiques","titre":"Connaître les principes de la régulation de la kaliémie","contenu":"<p>Le <span class=\"kw-def\">potassium</span> est le principal cation intracellulaire (<span class=\"kw-chiffre\">98 %</span> en intracellulaire) ; sa concentration extracellulaire (<span class=\"kw-chiffre\">3,5-5 mmol/L</span>) est finement régulée car elle détermine le <span class=\"kw-def\">potentiel membranaire de repos</span>.</p>\n      <table >\n        <thead><tr><th>Régulation interne (transfert via Na⁺/K⁺-ATPase)</th><th>Effet</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Insuline</span>, catécholamines <span class=\"kw-ttt\">β-adrénergiques</span>, <span class=\"kw-etio\">alcalose</span></td><td>entrée du K⁺ dans la cellule → <span class=\"kw-def\">hypokaliémie</span></td></tr>\n          <tr><td>Carence en <span class=\"kw-ttt\">insuline</span>, <span class=\"kw-etio\">acidose</span>, effet α-adrénergique</td><td>sortie / blocage d'entrée → <span class=\"kw-def\">hyperkaliémie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Régulation externe</strong> — le <span class=\"kw-clinique\">rein</span> est l'organe principal du bilan potassique : réabsorption proximale (<span class=\"kw-chiffre\">90 %</span>), ajustement fin au <span class=\"kw-def\">canal collecteur</span> via l'<span class=\"kw-bio\">aldostérone</span> et le canal <span class=\"kw-def\">ROMK</span> (feedback : ↑ <span class=\"kw-bio\">kaliémie</span> → ↑ aldostérone → ↑ kaliurèse). L'absorption digestive n'est quasiment pas régulée.</p>\n      <div class=\"obj-callout success\"><strong>À comprendre.</strong> Deux leviers : le <span class=\"kw-def\">transfert transcellulaire</span> (rapide — <span class=\"kw-ttt\">insuline</span>, β, <span class=\"kw-bio\">pH</span>) déplace le K⁺ sans changer le stock ; l'<span class=\"kw-bio\">excrétion rénale</span> (aldostérone) ajuste le bilan réel. Acidose → hyperkaliémie ; alcalose/<span class=\"kw-ttt\">insuline</span> → hypokaliémie.</div>","frequence":0},{"id":"267-13","rang":"A","rubrique":"Définition","titre":"Connaître les indications de prescription d’une kaliémie et définition de l’hyperkaliémie","contenu":"<table >\n        <thead><tr><th>Définition</th><th>Seuil</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Hyperkaliémie</strong></span></td><td><span class=\"kw-chiffre\">&gt; 5 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Hyperkaliémie menaçante</strong></span></td><td><span class=\"kw-chiffre\">&gt; 6,5 mmol/L</span> ou <span class=\"kw-alerte\">signes ECG</span> (hors ondes T amples isolées)</td></tr>\n        </tbody>\n      </table>\n      <p>L'hyperkaliémie <span class=\"kw-def\">diminue l'excitabilité membranaire</span> (réduit le gradient transcellulaire) → favorise <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">troubles de conduction</span>.</p>\n      <p><strong>Éliminer une fausse hyperkaliémie</strong> (libération de K⁺ intracellulaire in vitro) :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Garrot</span> trop serré ou prolongé · centrifugation tardive (<span class=\"kw-clinique\">hémolyse</span> de prélèvement)</li>\n        <li><span class=\"kw-etio\">Hyperleucocytose</span> &gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> G/L</span> · <span class=\"kw-etio\">thrombocytémie</span> &gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1000</span> G/L</span></li>\n        <li><strong>CAT :</strong> recontrôle à la seringue, sans vide ni garrot</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> <span class=\"kw-chiffre\">&gt; 5</span> = hyperkaliémie ; <span class=\"kw-chiffre\">&gt; 6,5</span> ou <span class=\"kw-imagerie\">ECG</span> = menaçante. Une <span class=\"kw-bio\">kaliémie</span> élevée <span class=\"kw-clinique\">sans modification ECG</span> doit faire évoquer une <span class=\"kw-alerte\">fausse hyperkaliémie</span>.</div>","frequence":0},{"id":"267-14","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la symptomatologie clinique de l’hyperkaliémie","contenu":"<p>L'<span class=\"kw-def\">hyperkaliémie</span> réduit le <span class=\"kw-def\">gradient potassique transmembranaire</span> → <span class=\"kw-def\">diminue l'excitabilité</span> (paralysie, <span class=\"kw-clinique\">hypotension</span>, troubles de conduction). Souvent <span class=\"kw-clinique\">asymptomatique</span>, révélée par l'<span class=\"kw-bio\">ECG</span> ou la <span class=\"kw-bio\">biologie</span>.</p>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Sensitives</strong></span></td><td><span class=\"kw-clinique\">paresthésies</span>, <span class=\"kw-clinique\">brûlures</span> des extrémités et péribuccales (sensibilité pallesthésique et thermoalgique)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Motrices</strong></span></td><td><span class=\"kw-clinique\">faiblesse musculaire</span> → <span class=\"kw-alerte\">paralysie flasque ascendante</span> (<span class=\"kw-clinique\">membres inférieurs</span> → muscles cervicaux → <span class=\"kw-clinique\">muscles respiratoires</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Hémodynamiques</strong></span></td><td><span class=\"kw-alerte\">hypotension artérielle</span> (<span class=\"kw-alerte\">signe de gravité</span>, <span class=\"kw-clinique\">hypoexcitabilité myocardique</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> La <span class=\"kw-alerte\">paralysie flasque</span> s'accompagne toujours d'anomalies <span class=\"kw-imagerie\">ECG</span> et <span class=\"kw-def\">annonce</span> un <span class=\"kw-alerte\">arrêt cardiaque imminent</span>.</div>","frequence":1},{"id":"267-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les anomalies ECG associées à l’hyperkaliémie","contenu":"<p>Toute suspicion d'hyperkaliémie impose un <span class=\"kw-alerte\">ECG immédiat</span> (avant même la confirmation <span class=\"kw-ttt\">biologique</span>). <span class=\"kw-clinique\">Les</span> anomalies apparaissent <span class=\"kw-clinique\">progressivement</span>, par ordre de gravité :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Anomalie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">1</span></td><td><span class=\"kw-clinique\">onde T ample, pointue, symétrique</span> (repolarisation accélérée) — non grave si isolée</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span></td><td>diminution puis disparition de l'<span class=\"kw-clinique\">onde P</span> (BSA, dysfonction sinusale)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span></td><td>allongement du <span class=\"kw-clinique\">PR</span> (BAV)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span></td><td>élargissement des <span class=\"kw-clinique\">QRS</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">5</span></td><td><span class=\"kw-alerte\">bradycardie à QRS large (« sine wave »)</span> → <span class=\"kw-alerte\">asystolie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-alerte\">Signes de gravité</span> <span class=\"kw-imagerie\">ECG</span></strong> (inefficacité cardiaque imminente) : <span class=\"kw-chiffre\">FC &lt; 50 bpm</span>, <span class=\"kw-alerte\">rythme jonctionnel</span>, <span class=\"kw-chiffre\">QRS &gt; 100 ms</span>. Mnémo : « la <span class=\"kw-clinique\">tête pointue</span> du grand-père (<span class=\"kw-clinique\">allongement PR</span>) élargit le curé (<span class=\"kw-clinique\">QRS large</span>) ».</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Pas de parallélisme strict entre niveau de <span class=\"kw-bio\">kaliémie</span> et sévérité <span class=\"kw-imagerie\">ECG</span> : l'<span class=\"kw-imagerie\">ECG</span> prime sur le chiffre pour décider de l'<span class=\"kw-alerte\">urgence</span> thérapeutique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 231 — <span class=\"kw-imagerie\">Électrocardiogramme</span> · 236 — Troubles de conduction</em></p>","frequence":7,"liens":[{"href":"https://www.e-cardiogram.com/hyperkaliemie-severe/","label":"e-cardiogram : Hyperkaliémie sévère (ECG)"}]},{"id":"267-16","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hyperkaliémies","contenu":"<p><strong>Trois principales causes :</strong> <span class=\"kw-etio\">acidose métabolique</span>, <span class=\"kw-etio\">insuffisance rénale aiguë</span>, <span class=\"kw-etio\">iatrogénie</span> (de loin la plus fréquente).</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Excès d'apport</strong></span></td><td>K⁺ IV/PO massif — rare sauf défaut d'excrétion associé (sels de régime)</td></tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Transfert vers l'extracellulaire</strong></span></td>\n            <td><span class=\"kw-etio\">carence en insuline</span> ; <span class=\"kw-etio\">hyperosmolarité</span> (mannitol, hyperglycémie) ; <span class=\"kw-etio\">acidose métabolique à TA normal</span> ; <span class=\"kw-etio\">catabolisme cellulaire</span> (rhabdomyolyse, lyse <span class=\"kw-etio\">tumorale</span>, hémolyse, brûlures) ; <span class=\"kw-etio\">médicaments</span> (β-bloquants non sélectifs, digitaliques, succinylcholine)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Défaut d'excrétion rénale</strong></span></td>\n            <td><span class=\"kw-etio\">IRA</span> (surtout si anurie) ; <span class=\"kw-etio\">IRC pré-terminale</span> ; <span class=\"kw-etio\">insuffisance surrénale (Addison)</span> ; <span class=\"kw-etio\">hyporéninisme-hypoaldostéronisme</span> (néphropathie diabétique, <span class=\"kw-etio\">VIH</span>) ; <span class=\"kw-etio\">iatrogène ++</span> : <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">diurétiques</span> épargneurs de K⁺ (amiloride, <span class=\"kw-ttt\">spironolactone</span>), anticalcineurines, <span class=\"kw-ttt\">héparine</span>, <span class=\"kw-ttt\">cotrimoxazole</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le contexte le plus fréquent : <span class=\"kw-etio\">IEC/ARA2</span> chez un patient en <span class=\"kw-clinique\">hypovolémie efficace</span> (DEC, <span class=\"kw-ci\">insuffisance cardiaque</span>) ou avec <span class=\"kw-etio\">IRC</span> sous-jacente. La kaliurèse oriente : &gt;<span class=\"kw-chiffre\"> 30 mmol/L</span> (excès d'apport, transfert) <span class=\"kw-bio\">vs</span> &lt;<span class=\"kw-chiffre\"> 30 mmol/L</span> (défaut d'excrétion).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë · 245 — Insuffisance surrénale · 330 — Classes de médicaments</em></p>","frequence":4},{"id":"267-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître le principe du traitement d’urgence de l’hyperkaliémie sévère","contenu":"<p>Indication : <span class=\"kw-alerte\">hyperkaliémie menaçante</span> (<span class=\"kw-chiffre\">&gt; 6,5 mmol/L</span> ou signes <span class=\"kw-imagerie\">ECG</span>). Stratégie en trois axes complémentaires, en parallèle de l'arrêt des apports et médicaments hyperkaliémiants.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Moyen · délai</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>1 · Antagonisme membranaire</strong></span></td>\n            <td><span class=\"kw-ttt\">Gluconate de calcium IV</span> (<span class=\"kw-chiffre\">1-3 min</span> ; protège le myocarde, <span class=\"kw-alerte\">ne baisse PAS la kaliémie</span>) — <span class=\"kw-ci\">CI si digitaliques</span> (utiliser chlorure de magnésium), <span class=\"kw-ci\">jamais mélangé au bicarbonate</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>2 · Transfert intracellulaire</strong></span></td>\n            <td><span class=\"kw-ttt\">Insuline IV + soluté G10 %</span> (−<span class=\"kw-chiffre\">0,5 à 1,2 mmol/L</span> en <span class=\"kw-chiffre\">1-2 h</span>) ; <span class=\"kw-ttt\">salbutamol</span> en nébulisation (effet additif)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>3 · Élimination</strong></span></td>\n            <td><span class=\"kw-ttt\">Furosémide</span> (si DEC absente) ; <span class=\"kw-ttt\">hémodialyse</span> = la plus rapide, indiquée si <span class=\"kw-alerte\">IRA anurique + hyperkaliémie menaçante sur ECG</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Réflexe.</strong> Devant des signes <span class=\"kw-imagerie\">ECG</span> d'hyperkaliémie : <span class=\"kw-ttt\">gluconate de calcium</span> en premier (membrane), puis <span class=\"kw-ttt\">insuline + G10 % + salbutamol</span> (transfert), puis épuration. Le calcium gagne du temps mais ne traite pas l'excès de K⁺.</div>","frequence":3},{"id":"267-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les autres possibilités de traitement d’urgence de l’hyperkaliémie sévère","contenu":"<table >\n        <thead><tr><th>Moyen</th><th>Modalités · limites</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Alcalinisation plasmatique</strong></span></td>\n            <td><span class=\"kw-ttt\">bicarbonate de sodium IV</span> — uniquement si <span class=\"kw-clinique\">acidose métabolique aiguë</span> à <span class=\"kw-bio\">trou anionique normal</span> ; délai <span class=\"kw-chiffre\">4-6 h</span> ; <span class=\"kw-ci\">jamais avec le calcium</span> (précipitation) ; risque de <span class=\"kw-alerte\">surcharge hydrosodée</span> ; effet négligeable en <span class=\"kw-etio\">IRC avancée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Résines échangeuses d'ions</strong></span></td>\n            <td><span class=\"kw-ttt\">sulfonate de polystyrène sodique (Kayexalate)</span> : échange K⁺/Na⁺, PO, en quelques heures ; <span class=\"kw-ttt\">Resikali</span> : K⁺/Ca⁺</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Cas particuliers</strong></span></td>\n            <td>intoxication digitalique → <span class=\"kw-ttt\">anticorps spécifiques</span> + <span class=\"kw-ttt\">chlorure de magnésium</span> (<span class=\"kw-ci\">carbonate de calcium CI</span>) ; hypoaldostéronisme → <span class=\"kw-ttt\">fludrocortisone</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> L'alcalinisation ne se justifie que sur une <span class=\"kw-clinique\">acidose métabolique aiguë associée</span> — ce n'est pas un traitement systématique de l'hyperkaliémie, et elle ne se mélange jamais au gluconate de calcium.</div>","frequence":0},{"id":"267-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement de l’hyperkaliémie chronique modérée","contenu":"<p>Contexte typique : <span class=\"kw-etio\">insuffisance rénale chronique</span>, où l'<span class=\"kw-def\">hyperkaliémie</span> reste <span class=\"kw-clinique\">modérée</span> et <span class=\"kw-clinique\">chronique</span>. Prise en charge non urgente, au long cours :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Restriction des apports potassiques</span> (diététique : éviter <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">sels de régime</span>, <span class=\"kw-etio\">fruits secs</span>, <span class=\"kw-etio\">chocolat</span>, légumes)</li>\n        <li><span class=\"kw-ttt\">Résines échangeuses d'ions</span> (<span class=\"kw-ttt\">sulfonate de polystyrène sodique</span>)</li>\n        <li><span class=\"kw-ttt\">Diurétiques hypokaliémiants</span> (<span class=\"kw-ttt\">furosémide</span>, <span class=\"kw-ttt\">thiazidique</span>) — possibles, non systématiques</li>\n        <li>Arrêt / adaptation des <span class=\"kw-etio\">médicaments hyperkaliémiants</span> (<span class=\"kw-etio\">IEC/ARA2</span>, <span class=\"kw-etio\">AINS</span>, <span class=\"kw-etio\">diurétiques épargneurs de K⁺</span>)</li>\n        <li>Correction d'une <span class=\"kw-bio\">acidose métabolique</span> associée (cible <span class=\"kw-bio\">bicarbonatémie</span> <span class=\"kw-chiffre\">&gt; 23 mmol/L</span>)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Sur <span class=\"kw-etio\">IRC</span>, l'<span class=\"kw-def\">hyperkaliémie chronique</span> se gère par la <span class=\"kw-ttt\">diététique</span> + <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">résines</span>, sans <span class=\"kw-alerte\">urgence</span> — l'objectif est d'éviter l'<span class=\"kw-alerte\">épisode aigu menaçant</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 326 — Cadre réglementaire de la prescription</em></p>","frequence":1},{"id":"267-20","rang":"A","rubrique":"Définition","titre":"Connaître les indications de prescription d’une kaliémie et définition de l’hypokaliémie","contenu":"<table >\n        <thead><tr><th>Définition</th><th>Seuil</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Hypokaliémie</strong></span></td><td><span class=\"kw-bio\">kaliémie</span> <span class=\"kw-chiffre\">&lt; 3,5 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Hypokaliémie menaçante</strong></span></td><td><span class=\"kw-chiffre\">&lt; 2,5 mmol/L</span> ou <span class=\"kw-alerte\">signes ECG</span></td></tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-def\">hypokaliémie</span> <span class=\"kw-def\">augmente l'excitabilité membranaire</span> (<span class=\"kw-def\">hyperpolarisation</span>) → favorise <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">troubles du rythme</span>. Le dosage de la <span class=\"kw-bio\">kaliémie</span> est demandé devant tout signe d'appel (musculaire, <span class=\"kw-imagerie\">ECG</span>) ou tout traitement <span class=\"kw-etio\">hypokaliémiant</span>.</p>\n      <p><strong>Éliminer une fausse hypokaliémie</strong> : <span class=\"kw-etio\">leucémie très hyperleucocytaire</span> avec <span class=\"kw-clinique\">prélèvement</span> laissé à température ambiante (captation du <span class=\"kw-bio\">K⁺</span> par <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">leucocytes</span>).</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> <span class=\"kw-chiffre\">&lt; 3,5</span> = <span class=\"kw-def\">hypokaliémie</span> ; <span class=\"kw-chiffre\">&lt; 2,5</span> ou <span class=\"kw-bio\">ECG</span> = menaçante. Premier réflexe : apprécier le retentissement <span class=\"kw-bio\">ECG</span>.</div>","frequence":0},{"id":"267-21","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes cliniques de l’hypokaliémie","contenu":"<table >\n        <thead><tr><th>Atteinte</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Muscles lisses</strong></span></td><td><span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">iléus paralytique</span> (syndrome d'<span class=\"kw-def\">Ogilvie</span>), retard de reprise du transit post-opératoire</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Muscles striés</strong></span></td><td><span class=\"kw-clinique\">crampes</span>, <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">faiblesse / paralysie par accès</span> (ascendante : MI → tronc → <span class=\"kw-clinique\">diaphragme</span>) ; <span class=\"kw-alerte\">rhabdomyolyse</span> si déplétion sévère</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Rénales (chronique)</strong></span></td><td><span class=\"kw-clinique\">syndrome polyuro-polydipsique</span> (<span class=\"kw-etio\">diabète insipide néphrogénique</span>) ; <span class=\"kw-bio\">alcalose métabolique</span> ; <span class=\"kw-etio\">néphropathie interstitielle chronique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Comme pour l'<span class=\"kw-def\">hyperkaliémie</span>, la <span class=\"kw-clinique\">faiblesse musculaire</span> débute aux <span class=\"kw-clinique\">membres inférieurs</span> et progresse de façon ascendante ; le risque ultime est la <span class=\"kw-alerte\">rhabdomyolyse</span> et l'<span class=\"kw-alerte\">atteinte respiratoire</span>.</div>","frequence":0},{"id":"267-22","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les anomalies ECG associées à l’hypokaliémie","contenu":"<p>L'hypokaliémie entraîne une <span class=\"kw-def\">hyperexcitabilité</span> par retard de repolarisation ventriculaire. Anomalies progressives :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Anomalie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">1</span></td><td><span class=\"kw-clinique\">sous-décalage du segment ST</span> ; allongement du <span class=\"kw-clinique\">PR</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span></td><td><span class=\"kw-clinique\">affaissement / inversion de l'onde T</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span></td><td>apparition d'une <span class=\"kw-clinique\">onde U</span> pathologique</td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span></td><td>allongement du <span class=\"kw-clinique\">QT</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">5-6</span></td><td>troubles du rythme : FA, puis ventriculaires (ESV, <span class=\"kw-alerte\">TV</span>, <span class=\"kw-alerte\">torsade de pointe ++</span>, <span class=\"kw-alerte\">FV</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-clinique\">QRS reste normal</span>. Facteurs aggravants : <span class=\"kw-etio\">hypercalcémie</span>, <span class=\"kw-etio\">hypomagnésémie</span> (favorise la torsade), <span class=\"kw-etio\">digitaliques</span>. Mnémo : « T'aplatis (T plate) – Hugh (onde U) – Grant (QT long) – sous cette (sous-décalage ST) – tornade (torsade) ».</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Dans l'hypokaliémie <span class=\"kw-clinique\">chronique</span> (<span class=\"kw-clinique\">anorexie</span> mentale), <span class=\"kw-clinique\">les</span> signes <span class=\"kw-imagerie\">ECG</span> peuvent manquer même à &lt;<span class=\"kw-chiffre\"> 3 mmol/L</span>. La <span class=\"kw-alerte\">torsade de pointe</span> est le danger, favorisée par une hypomagnésémie associée.</div>","frequence":2,"liens":[{"href":"https://www.e-cardiogram.com/hypokaliemie/","label":"e-cardiogram : Hypokaliémie (ECG)"}]},{"id":"267-23","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hypokaliémies","contenu":"<p><strong>Trois principales causes :</strong> <span class=\"kw-etio\">diarrhées</span>, <span class=\"kw-etio\">diurétiques</span>, <span class=\"kw-etio\">alcalose</span>. Signal d'appel : <span class=\"kw-clinique\">hypokaliémie + HTA</span> → rechercher un <span class=\"kw-alerte\">hyperminéralocorticisme</span>.</p>\n      <table >\n        <thead><tr><th>Kaliurèse</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>&lt; 20 mmol/L</strong></span> (réponse rénale appropriée)</td>\n            <td><span class=\"kw-etio\">carence d'apport</span> (<span class=\"kw-clinique\">anorexie</span> mentale) ; <span class=\"kw-etio\">transfert intracellulaire</span> (alcalose, <span class=\"kw-ttt\">insuline</span>, β-adrénergiques) ; <span class=\"kw-etio\">pertes digestives</span> (<span class=\"kw-clinique\">diarrhée</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>&gt; 20 mmol/L</strong></span> (perte rénale)</td>\n            <td>\n              <strong>Si <span class=\"kw-etio\">HTA</span> :</strong> <span class=\"kw-etio\">hyperminéralocorticisme</span> (hyperaldostéronisme I/II, <span class=\"kw-clinique\">syndrome de Liddle</span>, Cushing, réglisse)<br>\n              <strong>Si acidose :</strong> <span class=\"kw-etio\">acidocétose</span>, <span class=\"kw-etio\">acidose tubulaire rénale</span> (type 1 ou 2)<br>\n              <strong>Si alcalose :</strong> chlorurie basse (<span class=\"kw-etio\">vomissements</span>, mucoviscidose) ou élevée (<span class=\"kw-etio\">diurétiques</span>, <span class=\"kw-etio\">Bartter, Gitelman</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> L'arbre repose sur la <span class=\"kw-bio\">kaliurèse</span> (adaptée &lt; 20 <span class=\"kw-bio\">vs</span> inadaptée &gt; 20), puis sur la PA et le <span class=\"kw-bio\">pH</span>. <span class=\"kw-clinique\">Hypokaliémie + HTA</span> = hyperminéralocorticisme jusqu'à preuve du contraire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 245 — Insuffisance surrénale (hyperaldostéronisme)</em></p>","frequence":7},{"id":"267-24","rang":"A","rubrique":"Prise en charge","titre":"Connaître le principe du traitement d’urgence de l’hypokaliémie sévère","contenu":"<p>Indication : <span class=\"kw-alerte\">hypokaliémie menaçante</span> (<span class=\"kw-chiffre\">&lt; 2,5 mmol/L</span> ou signes <span class=\"kw-imagerie\">ECG</span>). Toujours associer un <span class=\"kw-ttt\">traitement étiologique</span> (arrêt des médicaments hypokaliémiants, correction d'une <span class=\"kw-bio\">hypomagnésémie</span>).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Non grave</strong></span> (&gt; 2,5, sans <span class=\"kw-imagerie\">ECG</span>)</td><td>supplémentation orale (<span class=\"kw-ttt\">KCl — Kaleorid, Diffu-K</span>) ; IV sur <span class=\"kw-chiffre\">24 h</span> si PO impossible</td></tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Menaçante</strong></span> (&lt; 2,5 ou <span class=\"kw-imagerie\">ECG</span>)</td>\n            <td>PO + <span class=\"kw-ttt\">KCl IVSE</span> : débit <span class=\"kw-chiffre\">1 g/h maximum</span> (<span class=\"kw-ci\">bolus proscrit = ACR irréversible</span>) ; dilué dans du soluté <span class=\"kw-clinique\">salé</span> (<span class=\"kw-ci\">éviter le glucosé</span> → insulinisme réactionnel) ; objectif <span class=\"kw-chiffre\">&gt; 3 mmol/L</span> ; <span class=\"kw-def\">surveillance</span> <span class=\"kw-imagerie\">ECG</span> + veine (KCl veinotoxique)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Selon l'<span class=\"kw-imagerie\">ECG</span> : <span class=\"kw-alerte\">torsade de pointe</span> → <span class=\"kw-ttt\">sulfate de magnésium</span> ; <span class=\"kw-clinique\">bradycardie</span> → <span class=\"kw-ttt\">isoprénaline</span>.</p>\n      <div class=\"callout callout-danger\"><strong>Piège vital.</strong> La supplémentation IV rapide ne dépasse jamais <span class=\"kw-chiffre\">1 g/h</span> et n'est <span class=\"kw-ci\">jamais en bolus</span> (risque d'<span class=\"kw-alerte\">arrêt cardiaque</span> irréversible). On dilue le KCl dans du salé, pas du glucosé.</div>","frequence":0},{"id":"267-25","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les indications de la gazométrie","contenu":"<p>La <span class=\"kw-bio\">gazométrie artérielle</span> s'envisage devant des <span class=\"kw-alerte\">signes de gravité</span> touchant un organe vital (poumon, cœur, rein, cerveau). Deux situations fréquentes :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Insuffisance respiratoire</strong></span></td><td><span class=\"kw-clinique\">dyspnée</span> (<span class=\"kw-clinique\">dyspnée</span> de Kussmaul → acidose métabolique) ; pathologie pulmonaire hypoxémiante ; hypo/hyperventilation ; IRespC</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Anomalie métabolique</strong></span></td><td><span class=\"kw-etio\">IRA sévère / oligo-anurie</span> ; <span class=\"kw-etio\">état de choc</span> (hyperlactatémie) ; <span class=\"kw-etio\">diarrhée importante</span> ; <span class=\"kw-etio\">acidocétose diabétique</span> ; <span class=\"kw-etio\">intoxications</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Valeurs normales (sang artériel)</strong> — prélevé en seringue héparinée, sans <span class=\"kw-clinique\">bulle</span> d'<span class=\"kw-def\">air</span> :</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">pH</span></td><td><span class=\"kw-chiffre\">7,38 – 7,42</span></td></tr>\n          <tr><td><span class=\"kw-bio\">PaCO₂</span></td><td><span class=\"kw-chiffre\">35 – 45 mmHg</span></td></tr>\n          <tr><td><span class=\"kw-bio\">HCO₃⁻</span></td><td><span class=\"kw-chiffre\">22 – 26 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\">PaO₂</span></td><td><span class=\"kw-chiffre\">80 – 100 mmHg</span> (<span class=\"kw-def\">air</span> ambiant)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir (descriptif CUEN).</strong> Indications types : <span class=\"kw-clinique\">choc, souffrance tissulaire, insuffisance respiratoire aiguë et chronique, diabète décompensé, intoxications responsables d'acidose métabolique</span>.</div>","frequence":0},{"id":"267-26","rang":"B","rubrique":"Éléments physiopathologiques","titre":"Connaître les mécanismes de régulation de l’équilibre acide-base","contenu":"<p>Le <span class=\"kw-def\">pH</span> exprime la concentration en H⁺, finement régulée. Le principal système tampon est le couple <span class=\"kw-def\">acide carbonique / bicarbonate</span>, dit « ouvert » :</p>\n      <ul>\n        <li>l'acide volatil (<span class=\"kw-bio\">PaCO₂</span>) est éliminé par la <span class=\"kw-clinique\">respiration</span></li>\n        <li>le <span class=\"kw-bio\">bicarbonate (HCO₃⁻)</span>, <span class=\"kw-bio\">réserve alcaline</span>, est régénéré par le <span class=\"kw-clinique\">rein</span></li>\n      </ul>\n      <table >\n        <thead><tr><th>Source d'acide</th><th>Élimination</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Acides volatils</span> (CO₂, métabolisme oxydatif)</td><td><span class=\"kw-clinique\">poumon</span> — défaut → <span class=\"kw-alerte\">acidose respiratoire</span></td></tr>\n          <tr><td><span class=\"kw-def\">Acides fixes</span> (métabolisme des protéines)</td><td><span class=\"kw-clinique\">rein</span> (excrétion de H⁺ via NH₄⁺) — défaut → <span class=\"kw-alerte\">acidose métabolique</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Réponses compensatrices</strong> : la compensation <span class=\"kw-clinique\">respiratoire</span> est rapide (minutes), la compensation <span class=\"kw-clinique\">rénale</span> est lente (heures). En aigu, la compensation limite le désordre sans ramener le <span class=\"kw-bio\">pH</span> à 7,40 ; en chronique, le retour à 7,40 est possible. Équation de <span class=\"kw-def\">Henderson-Hasselbalch</span>.</p>\n      <div class=\"obj-callout success\"><strong>À comprendre.</strong> Poumon = régulation rapide de la PaCO₂ ; rein = régulation lente du HCO₃⁻ (réabsorption proximale + excrétion distale des H⁺). Tout trouble primitif de l'un déclenche une compensation par l'autre.</div>","frequence":0},{"id":"267-27","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un trouble acido-basique, de son caractère métabolique ou ventilatoire","contenu":"<p>L'interprétation suit <span class=\"kw-def\">trois étapes</span> :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Question · seuils</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>1 · Acidose ou alcalose ?</strong></span></td><td><span class=\"kw-bio\">pH &lt; 7,38</span> = acidose (acidémie) ; <span class=\"kw-bio\">pH &gt; 7,42</span> = alcalose (alcalémie) ; un <span class=\"kw-bio\">pH</span> normal n'exclut pas un trouble (désordres associés)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>2 · Métabolique ou ventilatoire ?</strong></span></td><td><strong>Métabolique :</strong> anomalie primitive du <span class=\"kw-bio\">HCO₃⁻</span> (&lt; 22 acidose ; &gt; 26 alcalose)<br><strong>Respiratoire/ventilatoire :</strong> anomalie primitive de la <span class=\"kw-bio\">PCO₂</span> (&gt; 45 acidose ; &lt; 35 alcalose)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>3 · Simple ou complexe ?</strong></span></td><td>la compensation est-elle adaptée ? <span class=\"kw-def\">Formule de Winter</span> : <span class=\"kw-chiffre\">PaCO₂ attendue = 1,5 × [HCO₃⁻] + 8 ± 2</span></td></tr>\n        </tbody>\n      </table>\n      <p>Pour une <strong>acidose métabolique</strong> : si PaCO₂ mesurée ≈ attendue → <span class=\"kw-def\">simple</span> ; &gt; attendue → <span class=\"kw-def\">mixte</span> ; &lt; attendue → acidose métabolique + <span class=\"kw-def\">alcalose respiratoire</span>.</p>\n      <table >\n        <thead><tr><th>Trouble</th><th><span class=\"kw-bio\">pH</span></th><th>HCO₃⁻</th><th>PaCO₂</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Acidose métabolique</span></td><td>&lt; 7,38</td><td>↓ (primitif)</td><td>↓ (compensation)</td></tr>\n          <tr><td><span class=\"kw-def\">Acidose respiratoire</span></td><td>&lt; 7,38</td><td>↑ (compensation)</td><td>↑ (primitif)</td></tr>\n          <tr><td><span class=\"kw-def\">Alcalose métabolique</span></td><td>&gt; 7,42</td><td>↑ (primitif)</td><td>↑ (compensation)</td></tr>\n          <tr><td><span class=\"kw-def\">Alcalose respiratoire</span></td><td>&gt; 7,42</td><td>↓ (compensation)</td><td>↓ (primitif)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Méthode rapide : baisse de <span class=\"kw-chiffre\">1 mmol/L de HCO₃⁻</span> ≈ chute de <span class=\"kw-chiffre\">1 mmHg de PaCO₂</span>. La formule de Winter confirme le caractère simple ou complexe d'une acidose métabolique.</div>","frequence":2},{"id":"267-28","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les anomalies cliniques graves à rechercher","contenu":"<table >\n        <thead><tr><th>Trouble</th><th><span class=\"kw-alerte\">Signes de gravité</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Acidose métabolique sévère</strong></span></td>\n            <td><span class=\"kw-alerte\">urgence vitale si pH &lt; 7,10 ou HCO₃⁻ &lt; 8 mmol/L</span> : <span class=\"kw-alerte\">coma</span>, <span class=\"kw-clinique\">baisse du débit cardiaque</span> et tissulaire, <span class=\"kw-alerte\">résistance aux catécholamines</span>, <span class=\"kw-alerte\">arythmies ventriculaires</span> ; <span class=\"kw-clinique\">dyspnée de Kussmaul</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Acidose respiratoire (hypercapnie)</strong></span></td>\n            <td><span class=\"kw-clinique\">astérixis (flapping)</span>, <span class=\"kw-clinique\">agitation</span>/<span class=\"kw-clinique\">confusion</span> → <span class=\"kw-alerte\">coma hypercapnique</span> ; signes adrénergiques (<span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">HTA</span>) ; <span class=\"kw-clinique\">céphalées</span> (vasodilatation du CO₂)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Alcalose métabolique sévère</strong></span></td>\n            <td><span class=\"kw-alerte\">pH &gt; 7,60 = pronostic vital engagé</span> (risque d'<span class=\"kw-alerte\">arrêt respiratoire</span> par hypoventilation compensatrice)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Une <span class=\"kw-alerte\">hyperkaliémie menaçante</span> accompagne fréquemment l'acidose métabolique — rechercher systématiquement <span class=\"kw-clinique\">les</span> signes <span class=\"kw-imagerie\">ECG</span>. Tout trouble acido-basique sévère justifie une <span class=\"kw-alerte\">réanimation</span>.</div>","frequence":0},{"id":"267-29","rang":"A","rubrique":"Démarche diagnostique","titre":"Connaître les modalités du diagnostic d’une acidose métabolique liée à une insuffisance rénale, à une diarrhée, à une acidose lactique, à une acidocétose","contenu":"<p>Devant une acidose métabolique (<span class=\"kw-bio\">pH &lt; 7,38</span>, <span class=\"kw-bio\">HCO₃⁻ &lt; 22</span>), le <span class=\"kw-def\">trou anionique plasmatique (TA)</span> oriente le mécanisme : <span class=\"kw-chiffre\">TA = [Na⁺ + K⁺] − [Cl⁻ + HCO₃⁻]</span>.</p>\n      <table >\n        <thead><tr><th>TA augmenté (&gt; 16)</th><th>TA normal — hyperchlorémique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>accumulation d'un <span class=\"kw-def\">anion indosé</span> : <span class=\"kw-etio\">acidose lactique</span> (<span class=\"kw-alerte\">choc</span>, <span class=\"kw-ttt\">biguanides</span>, <span class=\"kw-alerte\">insuffisance hépatocellulaire</span>) ; <span class=\"kw-etio\">acidocétose</span> (<span class=\"kw-etio\">diabète</span>, jeûne, <span class=\"kw-etio\">alcool</span> — β-hydroxybutyrate) ; <span class=\"kw-etio\">IR sévère</span> (sulfates, phosphates) ; <span class=\"kw-etio\">intoxication</span> (<span class=\"kw-ttt\">aspirine</span>, éthylène glycol, méthanol)</td>\n            <td>perte de HCO₃⁻ compensée par le Cl⁻ ; <span class=\"kw-def\">trou anionique urinaire</span> [Nau + Ku] − Clu : <span class=\"kw-bio\">TU &lt; 0</span> → <span class=\"kw-etio\">pertes digestives (diarrhée)</span> ; <span class=\"kw-bio\">TU &gt; 0</span> → <span class=\"kw-etio\">acidose tubulaire rénale</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>4 éléments à doser en priorité</strong> (<span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>randes causes) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Glycémie + cétonémie/cétonurie</span> (<span class=\"kw-bio\">BU</span>) → <span class=\"kw-etio\">acidocétose</span></li>\n        <li><span class=\"kw-bio\">Lactate</span> → <span class=\"kw-etio\">acidose lactique</span></li>\n        <li><span class=\"kw-bio\">Créatininémie</span> → <span class=\"kw-etio\">insuffisance rénale</span></li>\n        <li>Recherche d'une <span class=\"kw-etio\">diarrhée</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir (descriptif CUEN).</strong> Savoir prendre en compte le contexte clinique et connaître la <span class=\"kw-def\">valeur d'orientation diagnostique du trou anionique plasmatique</span> : élevé = anion indosé (<span class=\"kw-bio\">lactate</span>, cétones, toxiques, IR) ; normal = perte de <span class=\"kw-bio\">bicarbonates</span> (<span class=\"kw-clinique\">diarrhée</span>, tubulopathie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> / acidocétose · 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë · 332 — État de <span class=\"kw-alerte\">choc</span></em></p>","frequence":6},{"id":"267-30","rang":"B","rubrique":"Démarche diagnostique","titre":"Savoir rechercher les causes toxiques et les acidoses tubulaires rénales","contenu":"<p><strong>Causes toxiques</strong> (acidose métabolique à TA augmenté, souvent avec <span class=\"kw-def\">trou osmotique</span>) : <span class=\"kw-etio\">salicylates (aspirine)</span>, <span class=\"kw-etio\">éthylène glycol</span> (antigel → oxalate), <span class=\"kw-etio\">méthanol</span> (→ formate).</p>\n      <p><strong>Acidoses tubulaires rénales</strong> — acidose hyperchlorémique (TA plasmatique normal), défaut tubulaire <span class=\"kw-clinique\">indépendant de l'insuffisance rénale</span> :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Distale (1)</th><th>Proximale (2)</th><th>Distale (4)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Mécanisme</span></td><td>défaut de sécrétion des H⁺ (canal collecteur)</td><td>défaut de réabsorption du HCO₃⁻ (TCP)</td><td>acidose distale + <span class=\"kw-def\">hyperkaliémie</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Kaliémie</span></td><td><span class=\"kw-def\">hypokaliémie</span>, corrigée par <span class=\"kw-clinique\">les</span> alcalins</td><td><span class=\"kw-def\">hypokaliémie</span>, aggravée par <span class=\"kw-clinique\">les</span> alcalins</td><td><span class=\"kw-def\">hyperkaliémie</span></td></tr>\n          <tr><td><span class=\"kw-bio\">pH urinaire</span></td><td><span class=\"kw-chiffre\">&gt; 5,5</span></td><td>peu modifié</td><td><span class=\"kw-chiffre\">&lt; 5,5</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Étiologies</span></td><td><span class=\"kw-clinique\">Gougerot-Sjögren</span>, <span class=\"kw-etio\">lupus</span>, <span class=\"kw-ttt\">amphotéricine B</span></td><td>Fanconi, myélome, ténofovir, acétazolamide</td><td>hyporéninisme-hypoaldostéronisme (<span class=\"kw-etio\">diabète</span>), anticalcineurines</td></tr>\n        </tbody>\n      </table>\n      <p>La principale forme d'élimination rénale des H⁺ est l'<span class=\"kw-def\">ion ammonium (NH₄⁺)</span> ; le <span class=\"kw-def\">trou anionique urinaire</span> en est le reflet inverse (réponse adaptée = <span class=\"kw-bio\">TU &lt; 0</span>).</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Acidose hyperchlorémique + TU urinaire &gt; 0 (NH₄⁺ bas) = <span class=\"kw-etio\">acidose tubulaire</span>. Le type 4 est le plus fréquent et se distingue par l'<span class=\"kw-def\">hyperkaliémie</span> (<span class=\"kw-bio\">vs</span> hypokaliémie des types 1 et 2).</div>","frequence":0},{"id":"267-31","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes d’acidose respiratoire","contenu":"<p>L'<span class=\"kw-def\">acidose respiratoire</span> résulte d'une <span class=\"kw-def\">hypoventilation alvéolaire</span> qui associe toujours <span class=\"kw-clinique\">hypoxémie</span> + <span class=\"kw-clinique\">hypercapnie</span>. En chronique, la compensation rénale (↑ <span class=\"kw-bio\">HCO₃⁻</span>) n'est jamais totale.</p>\n      <table >\n        <thead><tr><th>Niveau atteint</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Commande centrale</strong></span></td><td><span class=\"kw-etio\">médicaments dépresseurs respiratoires</span> (psychotropes, morphiniques) ; atteintes cérébrales (<span class=\"kw-etio\">AVC</span>, <span class=\"kw-etio\">traumatisme</span>, <span class=\"kw-etio\">infection</span>) ; syndrome d'<span class=\"kw-etio\">Ondine</span>, <span class=\"kw-etio\">SAS central</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Neuromusculaire</strong></span></td><td><span class=\"kw-etio\">Guillain-Barré</span>, <span class=\"kw-etio\">myasthénie</span>, <span class=\"kw-etio\">SLA</span> ; <span class=\"kw-etio\">trauma médullaire (&gt; C5)</span> ; <span class=\"kw-etio\">myopathies</span> ; troubles métaboliques (<span class=\"kw-etio\">hypokaliémie</span>, <span class=\"kw-etio\">hypophosphatémie</span>)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Thoraco-pulmonaire</strong></span></td><td><span class=\"kw-etio\">BPCO sévère</span>, <span class=\"kw-etio\">emphysème</span> ; pneumopathies inflammatoires avec myosite diaphragmatique (<span class=\"kw-etio\">lupus</span>, <span class=\"kw-etio\">polymyosite</span>) ; <span class=\"kw-etio\">cyphoscoliose</span>, <span class=\"kw-etio\">obésité</span>, <span class=\"kw-etio\">atteinte pleurale</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège.</strong> Dans <span class=\"kw-clinique\">les</span> pathologies <span class=\"kw-etio\">neuromusculaires</span>, les signes de <span class=\"kw-alerte\">détresse</span> respiratoire sont <span class=\"kw-alerte\">peu évidents</span> à l'examen (peu de mise en jeu visible des muscles accessoires) — l'hypercapnie peut être profonde sans tableau bruyant.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 209 — BPCO · 98 — Myasthénie · 97 — Polyradiculonévrites · 359 — <span class=\"kw-alerte\">Détresse</span> respiratoire aiguë</em></p>","frequence":1},{"id":"267-32","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de correction d’une acidose métabolique chronique","contenu":"<p>Contexte typique : <span class=\"kw-etio\">insuffisance rénale chronique</span>. Le traitement de l'<span class=\"kw-def\">acidose métabolique chronique</span> est <span class=\"kw-def\">préventif</span>, pour éviter <span class=\"kw-clinique\">les</span> conséquences au long cours.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Cible</strong></span></td><td><span class=\"kw-bio\">bicarbonatémie</span> <span class=\"kw-chiffre\">&gt; 23 mmol/L</span></td></tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Objectifs (prévention)</strong></span></td>\n            <td><span class=\"kw-clinique\">fonte musculaire</span> / <span class=\"kw-clinique\">catabolisme protéique</span> ; <span class=\"kw-clinique\">ostéodystrophie rénale</span> et <span class=\"kw-clinique\">déminéralisation osseuse</span> ; <span class=\"kw-alerte\">aggravation de l'hyperkaliémie</span> ; <span class=\"kw-clinique\">lithiase rénale</span> ; <span class=\"kw-clinique\">retard de croissance</span> (enfant)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Moyens</strong></span></td>\n            <td><span class=\"kw-ttt\">eau de Vichy</span> (<span class=\"kw-chiffre\">0,5-1 L</span>/j) ; ou <span class=\"kw-ttt\">alcalinisants</span> type <span class=\"kw-bio\">bicarbonate</span> de sodium (<span class=\"kw-ttt\">gélules de NaHCO₃</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Sur IRC, viser une <span class=\"kw-bio\">bicarbonatémie &gt; 23 mmol/L</span> par alcalinisation orale (eau de Vichy ou gélules de <span class=\"kw-bio\">bicarbonate</span>) — un geste simple à fort bénéfice osseux, musculaire et sur la <span class=\"kw-bio\">kaliémie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 268 — <span class=\"kw-bio\">Calcémie</span> (ostéodystrophie)</em></p>","frequence":0},{"id":"267-33","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge des troubles acido-basiques aigus sévères","contenu":"<p>Principe transversal : <span class=\"kw-alerte\">traiter la cause ++</span>. Pour l'acidose métabolique aiguë, l'alcalinisation n'est pas systématique.</p>\n      <table >\n        <thead><tr><th>Moyen</th><th>Modalités · indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Alcalinisation</strong></span></td>\n            <td><span class=\"kw-ttt\">bicarbonate de sodium IV</span> — objectifs <span class=\"kw-chiffre\">pH &gt; 7,20</span> et <span class=\"kw-chiffre\">HCO₃⁻ &gt; 10</span> ; <strong>indications :</strong> acidose hyperchlorémique, certaines intoxications, <span class=\"kw-alerte\">hyperkaliémie menaçante</span> ; <strong>non-indications :</strong> <span class=\"kw-ci\">acidocétose</span> (<span class=\"kw-ttt\">insuline</span> + réhydratation suffisent), surcharge hydrosodée, hypokaliémie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Risques de l'alcalinisation</strong></span></td>\n            <td><span class=\"kw-alerte\">hypokaliémie</span>, <span class=\"kw-alerte\">hypocalcémie</span>, alcalémie de rebond, surcharge hydrosodée</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Élimination du CO₂</strong></span></td>\n            <td>correction d'un bas débit, <span class=\"kw-ttt\">ventilation artificielle</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Épuration extra-rénale</strong></span></td>\n            <td><span class=\"kw-chiffre\">pH &lt; 7,20</span> + IRA organique ; <span class=\"kw-etio\">acidose lactique sévère de l'intoxication à la metformine</span> (élimine le <span class=\"kw-etio\">toxique</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>À retenir.</strong> <span class=\"kw-alerte\">Urgence</span> vitale si <span class=\"kw-chiffre\">pH &lt; 7,10</span> ou <span class=\"kw-chiffre\">HCO₃⁻ &lt; 8</span>. L'alcalinisation est <span class=\"kw-ci\">contre-indiquée dans l'acidocétose</span> (<span class=\"kw-ttt\">insuline</span> + réhydratation) et se discute dans l'acidose lactique — toujours surveiller la <span class=\"kw-bio\">kaliémie</span> et la <span class=\"kw-bio\">calcémie</span>.</div>","frequence":1},{"id":"267-34","rang":"A","rubrique":"Définition","titre":"Savoir dans quelles circonstances doit être prescrite une calcémie et définir l’hypocalcémie","contenu":"<p>L'<span class=\"kw-def\"><strong>hypocalcémie</strong></span> est une anomalie métabolique <span class=\"kw-clinique\">peu fréquente</span> (à l'inverse de l'hypercalcémie). On la confirme sur le <span class=\"kw-bio\">calcium ionisé</span>, seule fraction réellement régulée.</p>\n      <table >\n        <thead><tr><th>Définition <span class=\"kw-ttt\">biologique</span></th><th>Seuil</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Calcémie totale corrigée</strong></span></td><td><span class=\"kw-chiffre\">&lt; 2,20 mmol/L</span> <span class=\"kw-def\">(88 mg/L)</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Calcémie ionisée</strong></span></td><td><span class=\"kw-chiffre\">&lt; 1,15 mmol/L</span> → hypocalcémie <span class=\"kw-def\">« vraie »</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Éliminer une fausse hypocalcémie</strong> avant de conclure :</p>\n      <table >\n        <thead><tr><th>Piège</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Hypoalbuminémie</strong></span></td><td>abaisse le <span class=\"kw-bio\">calcium total</span> alors que le <span class=\"kw-bio\">calcium ionisé reste normal</span> (&gt;<span class=\"kw-chiffre\"> 40 %</span> du Ca est lié aux protéines)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Hyperalbuminémie</strong></span></td><td>peut au contraire <span class=\"kw-alerte\">masquer une vraie hypocalcémie</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Calcémie corrigée</strong></span></td><td><span class=\"kw-chiffre\">Ca corrigée = Ca total + [(40 − albuminémie) × 0,025]</span> <span class=\"kw-def\">(albumine en g/L)</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Dogme.</strong> Tout bilan d'une dyscalcémie doit comporter un <span class=\"kw-bio\">calcium ionisé</span> et/ou un <span class=\"kw-bio\">dosage d'albumine</span>. Doser la <span class=\"kw-bio\">calcémie</span> devant des <span class=\"kw-clinique\">signes d'hyperexcitabilité neuromusculaire</span> ou en contexte à risque (post-<span class=\"kw-ttt\">chirurgie</span> cervicale, IRC).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie</em></p>","frequence":0},{"id":"267-35","rang":"B","rubrique":"Éléments physiopathologiques","titre":"Comprendre les mécanismes de l’hypocalcémie","contenu":"<p>La <span class=\"kw-bio\">calcémie</span> est maintenue par deux hormones — la <span class=\"kw-bio\">PTH</span> et la <span class=\"kw-bio\">vitamine D active (calcitriol)</span> — agissant sur l'<span class=\"kw-clinique\">os</span>, l'<span class=\"kw-clinique\">intestin</span> et le <span class=\"kw-clinique\">rein</span>. L'hypocalcémie survient quand la <span class=\"kw-def\">perte nette de calcium</span> du secteur extracellulaire dépasse <span class=\"kw-clinique\">les</span> apports venus de l'intestin et de l'os.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Situations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Diminution des entrées</strong></span></td><td><span class=\"kw-etio\">malabsorption intestinale</span> ; <span class=\"kw-etio\">carence ou résistance à la vitamine D</span> ; <span class=\"kw-etio\">défaut de PTH</span> (↓ résorption osseuse)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Augmentation des pertes</strong></span></td><td><span class=\"kw-etio\">précipitation / dépôts tissulaires</span> ; <span class=\"kw-etio\">transfert osseux</span> (os affamé) ; <span class=\"kw-etio\">pertes urinaires</span> ; <span class=\"kw-etio\">chélation intravasculaire</span> (phosphate, citrate)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout success\"><strong>À comprendre.</strong> La <span class=\"kw-bio\">PTH</span> est le garde-fou : toute hypocalcémie <span class=\"kw-clinique\">aiguë</span> s'accompagne normalement d'une <span class=\"kw-bio\">PTH réactionnelle élevée</span> (réponse adaptée). Une <span class=\"kw-bio\">PTH normale ou basse</span> face à une hypocalcémie est <span class=\"kw-alerte\">inadaptée</span> = hypoparathyroïdie. Exception : l'hypocalcémie post-parathyroïdectomie (sidération des parathyroïdes + os affamé).</div>","frequence":0},{"id":"267-36","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux signes cliniques associés à l’hypocalcémie","contenu":"<p><span class=\"kw-clinique\">Les</span> signes traduisent une <span class=\"kw-def\">hyperexcitabilité neuromusculaire et myocardique</span>. Leur intensité dépend de la <span class=\"kw-clinique\">profondeur</span> et de la <span class=\"kw-clinique\">rapidité d'installation</span> : une hypocalcémie <span class=\"kw-clinique\">aiguë</span> est bien moins tolérée qu'une forme progressive.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Tétanie patente</strong></span></td><td><span class=\"kw-clinique\">crise tétanique</span> : paresthésies distales → contractures (<span class=\"kw-clinique\">main d'accoucheur</span>, bouche en <span class=\"kw-clinique\">museau de carpe</span>, spasme carpo-pédal) ; cède spectaculairement au <span class=\"kw-ttt\">calcium IV</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Tétanie latente</strong></span></td><td>signe de <span class=\"kw-clinique\">Chvostek</span> (percussion du nerf facial) · signe de <span class=\"kw-clinique\">Trousseau</span> (main d'accoucheur au brassard) · hyperréflexie ostéotendineuse</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Signes graves</strong></span></td><td><span class=\"kw-alerte\">laryngospasme</span>, <span class=\"kw-alerte\">bronchospasme</span>, <span class=\"kw-alerte\">spasme phrénique</span> → arrêt cardiorespiratoire ; <span class=\"kw-alerte\">comitialité</span> (enfant)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Troubles trophiques (chronique)</strong></span></td><td>peau/phanères secs, altération de l'émail · <span class=\"kw-clinique\">cataracte sous-capsulaire</span> · syndrome de <span class=\"kw-etio\">Fahr</span> (calcification des noyaux gris → <span class=\"kw-clinique\">syndrome extrapyramidal</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une hypocalcémie <span class=\"kw-alerte\">sévère (&lt; 1,8 mmol/L)</span> ou d'installation brutale peut engager le <span class=\"kw-alerte\">pronostic vital</span> (laryngospasme, spasme phrénique) → <span class=\"kw-ttt\">calcium IV</span> sans délai.</div>","frequence":1},{"id":"267-37","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principales anomalies ECG associées à l’hypocalcémie","contenu":"<p>L'hypocalcémie augmente l'<span class=\"kw-def\">excitabilité myocardique</span> ; un <span class=\"kw-bio\">ECG</span> fait partie du bilan de retentissement.</p>\n      <table >\n        <thead><tr><th>Cible</th><th>Anomalie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Repolarisation</strong></span></td><td><span class=\"kw-clinique\">allongement du QT</span> par allongement du <span class=\"kw-clinique\">segment ST</span> (onde T inchangée) : <span class=\"kw-chiffre\">QT &gt; 440 ms (♂) / &gt; 460 ms (♀)</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Conduction</strong></span></td><td>troubles de conduction (<span class=\"kw-clinique\">BAV</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Rythme</strong></span></td><td>troubles du rythme ventriculaire (<span class=\"kw-alerte\">TV</span>, <span class=\"kw-alerte\">FV</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Myocarde</strong></span></td><td><span class=\"kw-etio\">insuffisance cardiaque</span> (cardiomyopathie dilatée) si hypocalcémie prolongée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> L'<span class=\"kw-clinique\">allongement du QT</span> se fait ici aux dépens du <span class=\"kw-clinique\">segment ST</span> sans modifier l'onde T — image inverse de l'hypercalcémie (QT court). Le danger est la <span class=\"kw-alerte\">torsade de pointe / FV</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 231 — <span class=\"kw-imagerie\">ECG</span></em></p>","frequence":0,"liens":[{"href":"https://www.e-cardiogram.com/hypocalcemie/","label":"e-cardiogram : Hypocalcémie (ECG)"}]},{"id":"267-38","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires utiles au diagnostic étiologique de l’hypocalcémie","contenu":"<p>Une fois la vraie hypocalcémie confirmée (<span class=\"kw-bio\">Ca total</span> + <span class=\"kw-bio\">Ca ionisé</span> et/ou albuminémie), le <span class=\"kw-def\">diagnostic étiologique</span> repose sur le couple <span class=\"kw-bio\">PTH–phosphatémie</span>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Confirmation</strong></span></td><td><span class=\"kw-bio\">calcium total</span>, <span class=\"kw-bio\">calcium ionisé</span> et/ou <span class=\"kw-bio\">albuminémie</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Bilan étiologique</strong></span></td><td><span class=\"kw-bio\">phosphatémie</span> · <span class=\"kw-bio\">PTH</span> · <span class=\"kw-bio\">25-OH-vitamine D</span> · <span class=\"kw-bio\">calcitriol (1,25-OH-vitamine D)</span> · <span class=\"kw-bio\">calciurie des 24 h</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Retentissement</strong></span></td><td><span class=\"kw-bio\">ECG ++</span> (<span class=\"kw-imagerie\">EMG</span> / <span class=\"kw-imagerie\">EEG</span> non indispensables) ; atteinte osseuse : marqueurs du remodelage, <span class=\"kw-bio\">DMO</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La <span class=\"kw-bio\">PTH</span> oriente d'emblée : <span class=\"kw-bio\">PTH basse/normale</span> = hypoparathyroïdie ; <span class=\"kw-bio\">PTH élevée</span> = réaction adaptée (carence en <span class=\"kw-bio\">vitamine D</span>, IRC, résistance). La <span class=\"kw-bio\">phosphatémie</span> et la <span class=\"kw-bio\">calciurie</span> affinent l'étiologie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie</em></p>","frequence":0},{"id":"267-39","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hypocalcémies (arbre diagnostique)","contenu":"<p>L'<span class=\"kw-def\">arbre diagnostique</span> se lit à partir de la <span class=\"kw-bio\">PTH</span>, couplée à la <span class=\"kw-bio\">phosphatémie</span>, à la <span class=\"kw-bio\">vitamine D</span> et à la <span class=\"kw-bio\">calciurie</span>.</p>\n      <table >\n        <thead><tr><th>Orientation</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>PTH basse / inadaptée</strong></span><br>(hypoparathyroïdie)</td>\n            <td><span class=\"kw-etio\">post-chirurgicale +++</span> (thyroïde / parathyroïde / cervicale) ; <span class=\"kw-etio\">auto-immune</span> (Ac anti-CaSR) ; <span class=\"kw-etio\">infiltrative</span> (amylose, <span class=\"kw-etio\">hémochromatose</span>, Wilson, métastases) ; <span class=\"kw-etio\">hypomagnésémie sévère</span> ; <span class=\"kw-etio\">génétique : DiGeorge (22q11) ++</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>PTH élevée</strong></span><br>(réaction adaptée)</td>\n            <td><span class=\"kw-etio\">carence / résistance à la vitamine D</span> (malabsorption, cirrhose, médicaments : antiprotéases, anticonvulsivants, <span class=\"kw-ttt\">corticoïdes</span>) ; <span class=\"kw-etio\">IRC avancée</span> ; <span class=\"kw-etio\">pseudo-hypoparathyroïdie</span> (<span class=\"kw-bio\">PTH</span> très élevée, résistance — Albright) ; <span class=\"kw-etio\">hypocalcémie hypercalciurique familiale</span> (calciurie élevée)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Hypocalcémie aiguë</strong></span><br>(<span class=\"kw-bio\">PTH</span> élevée)</td>\n            <td><span class=\"kw-etio\">chélation</span> : phosphate (rhabdomyolyse, lyse <span class=\"kw-etio\">tumorale</span>), citrate (transfusion massive), foscarnet ; <span class=\"kw-etio\">précipitation tissulaire</span> (<span class=\"kw-clinique\">pancréatite aiguë</span>) ; <span class=\"kw-etio\">syndrome de l'os affamé</span> (post-parathyroïdectomie) ; <span class=\"kw-etio\">alcalose respiratoire aiguë</span> (spasmophilie) ; <span class=\"kw-etio\">biphosphonates, dénosumab</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Doser la <span class=\"kw-bio\">PTH</span> en premier. <span class=\"kw-bio\">Phosphatémie élevée</span> + <span class=\"kw-bio\">PTH</span> basse = hypoparathyroïdie ; phosphatémie basse + <span class=\"kw-bio\">PTH</span> haute = carence en <span class=\"kw-bio\">vitamine D</span>. Une <span class=\"kw-bio\">calciurie élevée</span> isole l'hypocalcémie hypercalciurique familiale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 358 — <span class=\"kw-clinique\">Pancréatite aiguë</span> · 189 — Déficit immunitaire · 279 — Cirrhose</em></p>","frequence":1},{"id":"267-40","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des hypocalcémies","contenu":"<p><span class=\"kw-def\">Traitement étiologique en premier lieu</span> dès qu'une cause est curable. Le reste associe <span class=\"kw-ttt\">calcium</span> ± <span class=\"kw-ttt\">vitamine D</span>, modulé selon le caractère aigu ou chronique.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>Aiguë symptomatique</strong></span></td><td><span class=\"kw-ttt\">gluconate ou chlorure de calcium IV lente</span> puis perfusion ; <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">clinique / ECG</span> ; corriger une <span class=\"kw-bio\">hypomagnésémie</span> ; suspendre <span class=\"kw-clinique\">les</span> médicaments allongeant le QT</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Apport calcique oral</strong></span></td><td><span class=\"kw-ttt\">carbonate de calcium</span><span class=\"kw-chiffre\"> 500 mg</span>–<span class=\"kw-chiffre\">1,5 g</span>/j (<span class=\"kw-ci\">≤ 500 mg si IRC</span>), <span class=\"kw-alerte\">en dehors des repas</span> (sinon sels insolubles)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Hypocalcémie chronique — quelle <span class=\"kw-bio\">vitamine D</span> selon la cause :</strong></p>\n      <table >\n        <thead><tr><th>Cause</th><th>Vitamine D</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Carence en vitamine D</strong></span></td><td><span class=\"kw-ttt\">vitamine D2 (ergocalciférol)</span> ou <span class=\"kw-ttt\">D3 (cholécalciférol)</span> + calcium PO</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Insuffisance rénale chronique</strong></span></td><td><span class=\"kw-ttt\">vitamine D 1-hydroxylée</span> (1-α-OH ou calcitriol) ; <span class=\"kw-ci\">pas si hyperphosphatémie</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Hypoparathyroïdie</strong></span></td><td><span class=\"kw-ttt\">calcium + vitamine D active</span> (calcitriol, car pas de <span class=\"kw-bio\">PTH</span> pour l'activer)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Pièges.</strong> En aigu, <span class=\"kw-ci\">ne jamais administrer de bicarbonate ni de phosphate</span> avec le calcium (précipitation). Dans l'hypoparathyroïdie, l'objectif est une <span class=\"kw-clinique\">calcémie minimale asymptomatique</span>, <span class=\"kw-alerte\">pas la normocalcémie</span> (risque d'hypercalciurie, de lithiase et de néphrocalcinose).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 268 — Hypercalcémie</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Hyperkaliémie menaçante <span class=\"q\">(<span class=\"kw-chiffre\">&gt; 6,5 mmol/L</span> ou signes <span class=\"kw-imagerie\">ECG</span>)</span></strong></p><p>arrêt des apports et médicaments hyperkaliémiants ; <span class=\"kw-ci\">gluconate de calcium CI si digitaliques</span>, <span class=\"kw-ci\">jamais mélangé au bicarbonate</span></p><ul><li><span class=\"kw-alerte\">ECG immédiat</span> avant même la confirmation <span class=\"kw-ttt\">biologique</span></li><li>1 · <span class=\"kw-ttt\">gluconate de calcium IV</span> (antagonisme membranaire, <span class=\"kw-chiffre\">1-3 min</span>) — <span class=\"kw-alerte\">ne baisse PAS la kaliémie</span></li><li>2 · <span class=\"kw-ttt\">insuline IV + soluté G10 %</span> + <span class=\"kw-ttt\">salbutamol</span> nébulisé (transfert intracellulaire, <span class=\"kw-chiffre\">1-2 h</span>)</li><li>3 · <span class=\"kw-ttt\">furosémide</span> ou <span class=\"kw-ttt\">hémodialyse</span> (élimination — la plus rapide)</li></ul><p><strong>Hyponatrémie sévère symptomatique <span class=\"q\">(<span class=\"kw-chiffre\">&lt; 120 mmol/L</span>)</span></strong></p><p>ne pas dépasser <span class=\"kw-chiffre\">10 mmol/L / 24 h</span> → risque de <span class=\"kw-alerte\">myélinolyse centro-pontine</span></p><ul><li><span class=\"kw-ttt\">NaCl hypertonique 3 %</span> en <span class=\"kw-alerte\">USI</span> pour <span class=\"kw-chiffre\">+ 5 mmol/L</span> initiaux</li><li>puis relais <span class=\"kw-ttt\">NaCl 0,9 %</span> jusqu'à <span class=\"kw-chiffre\">130 mmol/L</span></li></ul><p><strong>Hypokaliémie menaçante <span class=\"q\">(<span class=\"kw-chiffre\">&lt; 2,5 mmol/L</span> ou signes <span class=\"kw-imagerie\">ECG</span>)</span></strong></p><p><span class=\"kw-ci\">bolus proscrit</span> (<span class=\"kw-alerte\">arrêt cardiaque</span> irréversible) ; <span class=\"kw-ci\">éviter le glucosé</span> (insulinisme réactionnel)</p><ul><li><span class=\"kw-ttt\">KCl IVSE</span> : débit <span class=\"kw-chiffre\">1 g/h maximum</span>, dilué dans du soluté <span class=\"kw-clinique\">salé</span></li><li><span class=\"kw-alerte\">torsade de pointe</span> → <span class=\"kw-ttt\">sulfate de magnésium</span></li></ul><p><strong>Acidose métabolique sévère <span class=\"q\">(<span class=\"kw-chiffre\">pH &lt; 7,10</span> ou <span class=\"kw-chiffre\">HCO₃⁻ &lt; 8</span>)</span></strong></p><p><span class=\"kw-ci\">alcalinisation contre-indiquée dans l'acidocétose</span> (<span class=\"kw-ttt\">insuline</span> + réhydratation suffisent)</p><ul><li><span class=\"kw-alerte\">urgence vitale</span> → <span class=\"kw-alerte\">réanimation</span>, <span class=\"kw-alerte\">traiter la cause ++</span></li><li><span class=\"kw-ttt\">bicarbonate de sodium IV</span> selon indication (objectifs <span class=\"kw-chiffre\">pH &gt; 7,20</span>, <span class=\"kw-chiffre\">HCO₃⁻ &gt; 10</span>)</li></ul><p><strong>Hypocalcémie aiguë symptomatique</strong></p><p>cède spectaculairement au <span class=\"kw-ttt\">calcium IV</span> ; <span class=\"kw-ci\">ne jamais associer bicarbonate ni phosphate</span> (précipitation)</p><ul><li><span class=\"kw-ttt\">gluconate ou chlorure de calcium IV lente</span> puis perfusion</li><li>corriger une <span class=\"kw-bio\">hypomagnésémie</span> ; <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">ECG</span></li></ul>","hospit":"<p><strong>Unité de <span class=\"kw-alerte\">soins intensifs</span> (<span class=\"kw-alerte\">USI</span>) / réanimation</strong></p><ul><li><span class=\"kw-alerte\">hyponatrémie sévère symptomatique</span> (<span class=\"kw-chiffre\">&lt; 120</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-alerte\">convulsions</span>, <span class=\"kw-alerte\">coma</span>)</li><li>tout <span class=\"kw-alerte\">trouble acido-basique sévère</span> (acidose <span class=\"kw-chiffre\">pH &lt; 7,10</span>, alcalose <span class=\"kw-chiffre\">pH &gt; 7,60</span>)</li><li><span class=\"kw-alerte\">dyskaliémie menaçante</span> avec retentissement <span class=\"kw-imagerie\">ECG</span></li></ul><p><strong>Épuration extra-rénale (hémodialyse)</strong></p><ul><li>hyperkaliémie menaçante + <span class=\"kw-etio\">IRA anurique</span> (la plus rapide)</li><li>acidose métabolique <span class=\"kw-chiffre\">pH &lt; 7,20</span> + <span class=\"kw-etio\">IRA organique</span></li><li><span class=\"kw-etio\">acidose lactique sévère sur intoxication à la metformine</span> (élimine le <span class=\"kw-etio\">toxique</span>)</li></ul><p><strong>Avis spécialisé</strong></p><ul><li><span class=\"kw-etio\">SIADH</span> chronique réfractaire → <span class=\"kw-ttt\">tolvaptan</span> (antagoniste V2)</li></ul>","redflags":"<ul><li><span class=\"kw-def\">Hyponatrémie</span> : <span class=\"kw-alerte\">vomissements</span>, <span class=\"kw-alerte\">comitialité</span>, <span class=\"kw-alerte\">coma (Glasgow ≤ 8)</span> — surtout si aiguë ou <span class=\"kw-chiffre\">&lt; 120 mmol/L</span></li><li><span class=\"kw-def\">Hypernatrémie</span> : <span class=\"kw-alerte\">crise convulsive</span>, <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">hémorragies cérébro-méningées</span> / <span class=\"kw-alerte\">hématomes sous-duraux</span> (rétraction cérébrale)</li><li><span class=\"kw-def\">Hyperkaliémie</span> : <span class=\"kw-alerte\">paralysie flasque ascendante</span>, <span class=\"kw-alerte\">hypotension artérielle</span>, <span class=\"kw-imagerie\">ECG</span> <span class=\"kw-alerte\">QRS large « sine wave »</span> → <span class=\"kw-alerte\">asystolie</span></li><li><span class=\"kw-def\">Hypokaliémie</span> : <span class=\"kw-alerte\">torsade de pointe</span>, <span class=\"kw-alerte\">rhabdomyolyse</span>, paralysie ascendante atteignant le <span class=\"kw-clinique\">diaphragme</span></li><li><span class=\"kw-def\">Acidose métabolique</span> : <span class=\"kw-alerte\">pH &lt; 7,10</span> ou <span class=\"kw-alerte\">HCO₃⁻ &lt; 8</span>, <span class=\"kw-alerte\">résistance aux catécholamines</span>, <span class=\"kw-alerte\">arythmies ventriculaires</span>, <span class=\"kw-clinique\">dyspnée de Kussmaul</span></li><li><span class=\"kw-def\">Acidose respiratoire</span> : <span class=\"kw-clinique\">astérixis (flapping)</span> → <span class=\"kw-alerte\">coma hypercapnique</span></li><li><span class=\"kw-def\">Alcalose métabolique</span> : <span class=\"kw-alerte\">pH &gt; 7,60</span> = <span class=\"kw-alerte\">pronostic vital engagé</span> (<span class=\"kw-alerte\">arrêt respiratoire</span>)</li><li><span class=\"kw-def\">Hypocalcémie</span> : <span class=\"kw-alerte\">laryngospasme</span>, <span class=\"kw-alerte\">bronchospasme</span>, <span class=\"kw-alerte\">spasme phrénique</span>, crise tétanique</li></ul>","principes":"<p>Trois principes transversaux : <span class=\"kw-alerte\">traiter la cause ++</span> ; corriger selon le <strong>degré d'<span class=\"kw-alerte\">urgence</span> (symptômes)</strong> et l'<strong>état du secteur extracellulaire</strong> ; respecter strictement <span class=\"kw-clinique\">les</span> <strong>vitesses de correction</strong>.</p><p><strong>Hyponatrémie</strong></p><ul><li>dans tous <span class=\"kw-clinique\">les</span> cas <span class=\"kw-ttt\">restriction hydrique (500 mL/j)</span> ; limiter les solutés hypotoniques (<span class=\"kw-ci\">G5 %</span>)</li><li><span class=\"kw-def\">DEC</span> associée → <span class=\"kw-ttt\">NaCl isotonique 9 ‰</span></li><li><span class=\"kw-def\">euvolémie (SIADH)</span> → restriction ; si insuffisant <span class=\"kw-ttt\">urée per os</span> ou <span class=\"kw-ttt\">furosémide + sel</span> ; chronique <span class=\"kw-ttt\">tolvaptan</span></li><li><span class=\"kw-def\">HEC</span> associée → régime <span class=\"kw-ttt\">désodé (&lt; 2-4 g/24h)</span> + <span class=\"kw-ttt\">diurétiques de l'anse</span></li></ul><p><strong>Hypernatrémie</strong></p><p><span class=\"kw-ci\">ne jamais administrer d'eau pure IV</span> (hémolyse)</p><ul><li>apport d'eau : <span class=\"kw-ttt\">eau de boisson</span> PO/SNG, <span class=\"kw-ttt\">G5 % ou G2,5 %</span> IV, ou <span class=\"kw-ttt\">NaCl 0,45 %</span> si <span class=\"kw-clinique\">déshydratation</span> globale</li><li>HEC associée → <span class=\"kw-ttt\">diurétique de l'anse</span> + eau pure PO</li></ul><p><strong>Hyperkaliémie chronique modérée <span class=\"q\">(IRC)</span></strong></p><ul><li><span class=\"kw-ttt\">restriction des apports potassiques</span> (éviter sels de régime, fruits secs, chocolat)</li><li><span class=\"kw-ttt\">résines échangeuses d'ions</span> (sulfonate de polystyrène sodique)</li><li>arrêt / adaptation des <span class=\"kw-etio\">médicaments hyperkaliémiants</span> (<span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span>, <span class=\"kw-ttt\">AINS</span>, épargneurs de K⁺)</li><li>correction d'une <span class=\"kw-bio\">acidose métabolique</span> associée (cible <span class=\"kw-chiffre\">&gt; 23 mmol/L</span>)</li></ul><p><strong>Hypokaliémie non grave</strong></p><ul><li>supplémentation orale <span class=\"kw-ttt\">KCl (Kaleorid, Diffu-K)</span> ; IV sur <span class=\"kw-chiffre\">24 h</span> si PO impossible</li><li>toujours <span class=\"kw-ttt\">traiter la cause</span> + corriger une <span class=\"kw-bio\">hypomagnésémie</span></li></ul><p><strong>Acidose métabolique chronique <span class=\"q\">(IRC)</span></strong></p><p>geste simple à bénéfice osseux, musculaire et sur la <span class=\"kw-bio\">kaliémie</span></p><ul><li>cible <span class=\"kw-bio\">bicarbonatémie</span> <span class=\"kw-chiffre\">&gt; 23 mmol/L</span></li><li>alcalinisation orale : <span class=\"kw-ttt\">eau de Vichy</span> (<span class=\"kw-chiffre\">0,5-1 L</span>/j) ou <span class=\"kw-ttt\">gélules de bicarbonate de sodium</span></li></ul><p><strong>Hypocalcémie chronique</strong></p><ul><li><span class=\"kw-ttt\">carbonate de calcium</span> PO en dehors des repas (<span class=\"kw-ci\">≤ 500 mg/j si IRC</span>)</li><li><span class=\"kw-bio\">vitamine D</span> selon la cause : <span class=\"kw-ttt\">D2/D3</span> si carence, <span class=\"kw-ttt\">forme 1-hydroxylée (calcitriol)</span> si IRC ou hypoparathyroïdie</li></ul>","suivi":"<p><strong>Vitesse de correction des dysnatrémies</strong></p><p>corriger toute <span class=\"kw-bio\">hypokaliémie</span> associée (accélère la remontée de la <span class=\"kw-bio\">natrémie</span>)</p><ul><li><span class=\"kw-def\">Hyponatrémie</span> : <span class=\"kw-chiffre\">&lt; 10 mmol/L / 24 h</span> puis <span class=\"kw-chiffre\">&lt; 8 mmol/L</span> <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 h</span> suivantes → sinon <span class=\"kw-alerte\">myélinolyse centro-pontine</span></li><li><span class=\"kw-def\">Hypernatrémie</span> chronique : ↓ <span class=\"kw-chiffre\">0,5 mmol/L/h</span> (max <span class=\"kw-chiffre\">10 mmol/L/j</span>) ; aiguë : ↓ <span class=\"kw-chiffre\">1-2 mmol/L/h</span> → sinon <span class=\"kw-alerte\">œdème cérébral</span></li></ul><p><strong><span class=\"kw-def\">Surveillance</span> des dyskaliémies</strong></p><ul><li>monitorage <span class=\"kw-bio\">ECG</span> continu + <span class=\"kw-bio\">kaliémie</span> répétée ; l'<span class=\"kw-imagerie\">ECG</span> prime sur le chiffre</li><li>KCl IV : <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-clinique\">veine</span> (KCl veinotoxique), objectif <span class=\"kw-chiffre\">&gt; 3 mmol/L</span></li></ul><p><strong><span class=\"kw-def\">Surveillance</span> de l'hypocalcémie</strong></p><ul><li><span class=\"kw-bio\">ECG ++</span> (allongement du <span class=\"kw-clinique\">QT</span>) et <span class=\"kw-bio\">calcémie</span></li><li>hypoparathyroïdie : viser une <span class=\"kw-clinique\">calcémie minimale asymptomatique</span>, <span class=\"kw-alerte\">pas la normocalcémie</span> (risque de lithiase / néphrocalcinose)</li></ul>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique4","label":"Collège CUEN — Troubles de l'hydratation (dysnatrémies)"},{"href":"https://manuel4.cuen.fr/spip.php?rubrique5","label":"Collège CUEN — Anomalies du bilan du potassium"},{"href":"https://manuel4.cuen.fr/spip.php?rubrique7","label":"Collège CUEN — Désordres de l'équilibre acide-base"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/35.%20Gaz%20du%20sang%20et%20troubles%20de%20l%27%C3%A9quilibre%20acidobasique.pdf","label":"Collège CEMIR — Gaz du sang & troubles acido-basiques (PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/36.%20%C3%89tiologie%20des%20anomalies%20gazom%C3%A9triques%20d%27origine%20m%C3%A9tabolique.pdf","label":"Collège CEMIR — Étiologie des anomalies gazométriques métaboliques (PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/38.%20D%C3%A9sordres%20hydro%C3%A9lectrolytiques%20-%20dyskali%C3%A9mie.pdf","label":"Collège CEMIR — Désordres hydroélectrolytiques : dyskaliémie (PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/37.%20D%C3%A9sordres%20hydro%C3%A9lectrolytiques%2C%20anomalies%20du%20bilan%20de%20l%27eau.pdf","label":"Collège CEMIR — Désordres hydroélectrolytiques : bilan de l'eau (PDF)"},{"href":"https://www.sfendocrino.org/item-267-desordres-hydroelectrolytiques-dyskaliemie/","label":"SFEndocrino — Item 267 : dyskaliémie"},{"href":"https://www.sfendocrino.org/item-267-desordres-hydroelectrolytiques-hyponatremie/","label":"SFEndocrino — Item 267 : hyponatrémie"}],"cards":[{"i":"369ecdb45831","n":267,"o":"267-1","u":"Définition","t":"Connaître les indications de prescription et les seuils de définitions de la sévérité d’une hyponatrémie","q":"Comment évaluer la gravité clinique d'une hyponatrémie ?","a":"<p>La gravité d'une hyponatrémie est jugée sur les <strong>symptômes neurologiques</strong> (modérés vs. sévères) présentés par le patient, et non seulement sur le chiffre de natrémie.</p>"},{"i":"47ed65e2fc5e","n":267,"o":"267-1","u":"Définition","t":"Connaître les indications de prescription et les seuils de définitions de la sévérité d’une hyponatrémie","q":"Qu'est-ce qu'une hyponatrémie factice et dans quel contexte doit-on l'évoquer ?","a":"<p>Une hyponatrémie factice, ou pseudohyponatrémie, est une situation où la natrémie mesurée est basse, mais l'<strong>osmolalité plasmatique mesurée est normale ou élevée</strong>. Elle est due à un <strong>excès de solutés inactifs</strong> dans le plasma, qui diminue la phase aqueuse proportionnellement, mais pas la concentration réelle de sodium.</p><ul><li>Elle survient dans des contextes d'<strong>hyperprotidémie</strong> (ex: myélome) ou d'<strong>hyperlipidémie</strong>.</li><li>Dans ce cas, l'osmolalité plasmatique est <strong>normale</strong>.</li></ul>"},{"i":"f060b6377716","n":267,"o":"267-1","u":"Définition","t":"Connaître les indications de prescription et les seuils de définitions de la sévérité d’une hyponatrémie","q":"Comment définir une hyponatrémie et quels sont ses seuils de sévérité ?","a":"<p>Une hyponatrémie est définie par une natrémie <strong>inférieure à 135 mmol/L</strong>. Elle est considérée comme <strong>sévère si la natrémie est inférieure à 120 mmol/L</strong>. Elle traduit toujours un excès d'eau et s'accompagne d'une hypo-osmolalité plasmatique (< 280 mOsm/kg).</p>"},{"i":"f1ed1586bcb4","n":267,"o":"267-1","u":"Définition","t":"Connaître les indications de prescription et les seuils de définitions de la sévérité d’une hyponatrémie","q":"Qu'est-ce qu'une pseudo-hyponatrémie et comment la reconnaître ?","a":"<p>Une pseudo-hyponatrémie est une baisse de la natrémie mesurée due à un <strong>transfert d'eau du secteur intracellulaire vers le secteur extracellulaire</strong>, diluant le sodium plasmatique. Elle s'accompagne d'une <strong>hyperosmolalité plasmatique</strong>.</p><ul><li>Elle est typiquement observée en cas d'<strong>hyperglycémie</strong> majeure, ou d'intoxication au <strong>méthanol/éthanol</strong>.</li><li>La natrémie peut être corrigée par la formule de Katz : <span style=\"font-family: Times New Roman;\">[Na] + 0,3 × (glycémie − 5)</span>.</li></ul>"},{"i":"f43ee2aa944a","n":267,"o":"267-1","u":"Définition","t":"Connaître les indications de prescription et les seuils de définitions de la sévérité d’une hyponatrémie","q":"Quelle est la physiopathologie principale de l'hyponatrémie ?","a":"<p>L'hyponatrémie traduit toujours un <strong>excès d'eau</strong> par rapport au sodium, provoquant une <strong>hyperhydratation intracellulaire</strong>, et non un manque primitif de sodium.</p>"},{"i":"197feeb4aa53","n":267,"o":"267-10","u":"Étiologies","t":"Connaître les principales étiologies des hypernatrémies","q":"Comment distinguer un diabète insipide central d'un diabète insipide néphrogénique ?","a":"<p>La distinction se fait par l'<strong>épreuve de restriction hydrique</strong> associée à l'administration d'<strong>ADH exogène (ddAVP)</strong> :</p><ul><li>Si l'<strong>Uosm s'élève après l'ADH</strong>, il s'agit d'un diabète insipide <strong>central</strong>.</li><li>Si l'<strong>Uosm n'est pas modifiée</strong> par l'ADH, il s'agit d'un diabète insipide <strong>néphrogénique</strong>.</li></ul>"},{"i":"1ce2dfa2f37f","n":267,"o":"267-10","u":"Étiologies","t":"Connaître les principales étiologies des hypernatrémies","q":"Quelles sont les étiologies des hypernatrémies dues à des pertes extra-rénales ?","a":"<p>Les hypernatrémies par pertes extra-rénales se caractérisent par des <strong>urines concentrées</strong> (U/P osm > 1). Elles peuvent être :</p><ul><li><strong>Cutanées</strong> : coup de chaleur, brûlure.</li><li><strong>Respiratoires</strong>.</li><li><strong>Digestives</strong> : diarrhée osmotique.</li></ul>"},{"i":"4415fc066e60","n":267,"o":"267-10","u":"Étiologies","t":"Connaître les principales étiologies des hypernatrémies","q":"Quelles sont les causes d'hypernatrémie liées à des pertes rénales ?","a":"<p>Les causes rénales d'hypernatrémie sont :</p><ul><li>Le <strong>diabète insipide</strong> (central ou néphrogénique), caractérisé par une <strong>polyurie hypotonique</strong> (U/P osm < 1, Uosm < 300 mOsm/L).</li><li>La <strong>polyurie osmotique</strong> (ex : diabète sucré, mannitol).</li></ul>"},{"i":"8cbe2de07be1","n":267,"o":"267-10","u":"Étiologies","t":"Connaître les principales étiologies des hypernatrémies","q":"Quelles sont les causes d'hypernatrémie liées à un déficit d'apport en eau ?","a":"<p>Les causes d'hypernatrémie par déficit d'apport en eau incluent :</p><ul><li>Une <strong>hypodipsie primitive</strong> (anomalie hypothalamique).</li><li>Des <strong>difficultés d'accès à l'eau</strong> chez le nourrisson, le grabataire, ou en réanimation (coma, sédation).</li></ul>"},{"i":"d9865a6af860","n":267,"o":"267-10","u":"Étiologies","t":"Connaître les principales étiologies des hypernatrémies","q":"Dans quel contexte peut-on observer une hypernatrémie due à un apport massif de sodium ?","a":"<p>Un apport massif de sodium peut provoquer une hypernatrémie, surtout chez l'enfant, suite à l'administration de :</p><ul><li><strong>Soluté bicarbonaté hypertonique</strong>.</li><li><strong>Bain de dialyse trop riche en sodium</strong>.</li></ul>"},{"i":"e594af404226","n":267,"o":"267-10","u":"Étiologies","t":"Connaître les principales étiologies des hypernatrémies","q":"Quelles sont les principales causes de diabète insipide central ?","a":"<p>Les principales causes de diabète insipide central incluent :</p><ul><li>Les causes <strong>post-traumatiques ou post-chirurgie hypophysaire</strong>.</li><li>L'<strong>ischémie</strong> (choc, syndrome de Sheehan).</li><li>Les <strong>néoplasies</strong> (craniopharyngiome, germinome).</li><li>Les <strong>granulomes</strong> (sarcoïdose, histiocytose).</li></ul>"},{"i":"fbd4269cfd1d","n":267,"o":"267-10","u":"Étiologies","t":"Connaître les principales étiologies des hypernatrémies","q":"Quelles sont les principales causes de diabète insipide néphrogénique ?","a":"<p>Les principales causes de diabète insipide néphrogénique incluent :</p><ul><li>Les <strong>médicaments</strong> : <strong>lithium</strong>, amphotéricine B, déméclocycline.</li><li>Les désordres électrolytiques : <strong>hypercalcémie</strong>, <strong>hypokaliémie</strong>.</li><li>Les <strong>néphropathies interstitielles</strong>.</li><li>Les formes <strong>héréditaires</strong> (récepteur ADH lié à l'X).</li></ul>"},{"i":"2bd88a05be2d","n":267,"o":"267-11","u":"Prise en charge","t":"Connaître les principes du traitement des hypernatrémies","q":"Comment évalue-t-on le déficit en eau chez un patient hypernatrémique et quel est le principe général de sa correction ?","a":"<p>L'estimation du déficit en eau se calcule par la formule : <strong>60 % x poids x [(natrémie/140) - 1]</strong>. La correction se fait par un <strong>apport d'eau</strong>, dont les modalités sont modulées selon l'état du secteur extracellulaire.</p>"},{"i":"8173025c618b","n":267,"o":"267-11","u":"Prise en charge","t":"Connaître les principes du traitement des hypernatrémies","q":"Quels sont les pièges à éviter lors du traitement d'une hypernatrémie, notamment concernant la vitesse de correction et l'administration de solutés ?","a":"<ul><li>Il ne faut <strong>JAMAIS administrer d'eau pure par voie IV</strong> pour corriger une hypernatrémie, en raison du risque d'<strong>hémolyse</strong>.</li><li>La vitesse de correction doit être adaptée : <ul><li>En cas d'hypernatrémie chronique : la natrémie doit diminuer de <strong>0,5 mmol/L/h</strong> (maximum <strong>10 mmol/L/j</strong>).</li><li>En cas d'hypernatrémie aiguë : la natrémie doit diminuer de <strong>1 à 2 mmol/L/h</strong>.</li></ul>Un non-respect de ces vitesses de correction expose au risque d'<strong>œdème cérébral</strong>.</li></ul>"},{"i":"91ccde165a56","n":267,"o":"267-11","u":"Prise en charge","t":"Connaître les principes du traitement des hypernatrémies","q":"Quels sont les différents solutés et voies d'administration recommandés pour corriger une hypernatrémie, en fonction de l'état du volume extracellulaire (VEC) ?","a":"<ul><li>En cas de DIC isolée (déshydratation intracellulaire isolée) : <strong>eau de boisson per os ou par SNG</strong> (sonde nasogastrique), ou <strong>soluté glucosé G5% ou G2,5% IV</strong>.</li><li>En cas de déshydratation globale : <strong>NaCl 0,45% IV</strong>. Si la déplétion volémique est sévère, il faut <strong>corriger d'abord la volémie</strong> avec du NaCl 0,9%.</li><li>En cas de surcharge hydro-sodée (HEC associée) : <strong>diurétique de l'anse + eau pure (per os)</strong> ou <strong>soluté hypotonique (IV)</strong>.</li></ul>"},{"i":"02150aea9e87","n":267,"o":"267-13","u":"Définition","t":"Connaître les indications de prescription d’une kaliémie et définition de l’hyperkaliémie","q":"Quelle est la définition de l'hyperkaliémie d'après la valeur de la kaliémie ?","a":"<p>On définit une hyperkaliémie par une kaliémie <strong>supérieure à 5 mmol/L</strong>.</p>"},{"i":"a168186031f1","n":267,"o":"267-13","u":"Définition","t":"Connaître les indications de prescription d’une kaliémie et définition de l’hyperkaliémie","q":"Dans quel contexte une hyperkaliémie est-elle considérée comme menaçante ?","a":"<p>Une hyperkaliémie est considérée comme menaçante lorsque la kaliémie est <strong>supérieure à 6,5 mmol/L</strong>, ou en présence de <strong>signes électrocardiographiques</strong> (hors ondes T amples isolées).</p>"},{"i":"f1730238f523","n":267,"o":"267-13","u":"Définition","t":"Connaître les indications de prescription d’une kaliémie et définition de l’hyperkaliémie","q":"Quels mécanismes ou situations peuvent entraîner une fausse hyperkaliémie et comment l'éliminer ?","a":"<p>Une fausse hyperkaliémie peut être évoquée en cas de :<ul><li><strong>Garrot trop serré ou prolongé</strong>.</li><li><strong>Centrifugation tardive</strong> du prélèvement (avec hémolyse).</li><li><strong>Hyperleucocytose majeure</strong> (> 100 G/L).</li><li><strong>Thrombocytémie majeure</strong> (> 1000 G/L).</ul>Pour l'éliminer, il convient de <strong>recontrôler la kaliémie à la seringue</strong>, en évitant le garrot et les tubes sous vide.</p>"},{"i":"5adedaac9b39","n":267,"o":"267-15","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hyperkaliémie","q":"Quel est le principe majeur concernant la corrélation entre la kaliémie chiffrée et les anomalies ECG en cas d'hyperkaliémie ?","a":"<p>Il n'existe <strong>pas de parallélisme strict</strong> entre le niveau de kaliémie chiffré et la sévérité des anomalies ECG. L'<strong>ECG prime sur le chiffre</strong> de la kaliémie pour décider de l'urgence thérapeutique.</p>"},{"i":"6fbb065c5983","n":267,"o":"267-15","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hyperkaliémie","q":"Décrivez les anomalies électrocardiographiques progressives de l'hyperkaliémie, de la moins grave à la plus grave.","a":"<ul><li><strong>Onde T ample, pointue, symétrique</strong>.</li><li>Diminution puis <strong>disparition de l'onde P</strong>.</li><li><strong>Allongement du segment PR</strong>.</li><li><strong>Élargissement des QRS</strong>.</li><li><strong>Bradycardie à QRS large</strong> (aspect de « sine wave ») conduisant à l'asystolie.</li></ul>"},{"i":"c068b3f1341e","n":267,"o":"267-15","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hyperkaliémie","q":"Quels sont les signes ECG de gravité immédiate d'une hyperkaliémie, indiquant une inefficacité cardiaque imminente ?","a":"<p>Les signes ECG de gravité qui imposent une urgence thérapeutique sont une <strong>fréquence cardiaque inférieure à 50 bpm</strong>, la présence d'un <strong>rythme jonctionnel</strong> ou un <strong>élargissement des QRS supérieur à 100 ms</strong>.</p>"},{"i":"cef9094ab455","n":267,"o":"267-15","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hyperkaliémie","q":"Quelle est l'anomalie électrocardiographique initiale et non grave de l'hyperkaliémie ?","a":"<p>L'anomalie initiale et non grave de l'hyperkaliémie est une <strong>onde T ample, pointue et symétrique</strong>, témoignant d'une repolarisation accélérée.</p>"},{"i":"41dfe2ee188b","n":267,"o":"267-16","u":"Étiologies","t":"Connaître les principales étiologies des hyperkaliémies","q":"Quelles sont les causes d'hyperkaliémie par excès d'apport en potassium ou transfert vers le secteur extracellulaire ?","a":"<p>Les causes d'hyperkaliémie par un excès d'apport ou un transfert vers le secteur extracellulaire incluent :</p><ul><li>Excès d'apport : <strong>K⁺ IV/PO massif</strong> (rare, sauf si défaut d'excrétion associé ou sels de régime).</li><li>Transfert vers l'extracellulaire : <strong>carence en insuline</strong>, <strong>hyperosmolarité</strong> (mannitol, hyperglycémie), <strong>acidose métabolique</strong> à trou anionique normal, <strong>catabolisme cellulaire</strong> (rhabdomyolyse, lyse tumorale, hémolyse, brûlures), <strong>médicaments</strong> (β-bloquants non sélectifs, digitaliques, succinylcholine).</li></ul>"},{"i":"524abdd7bd30","n":267,"o":"267-16","u":"Étiologies","t":"Connaître les principales étiologies des hyperkaliémies","q":"Quelles sont les trois principales étiologies de l'hyperkaliémie ?","a":"<p>Les trois principales étiologies de l'hyperkaliémie sont :</p><ul><li>L'<strong>acidose métabolique</strong>.</li><li>L'<strong>insuffisance rénale aiguë</strong>.</li><li>L'<strong>iatrogénie</strong> (de loin la plus fréquente).</li></ul>"},{"i":"71da4d49b76f","n":267,"o":"267-16","u":"Étiologies","t":"Connaître les principales étiologies des hyperkaliémies","q":"Quel est le contexte clinique le plus fréquent de l'hyperkaliémie iatrogène ?","a":"<p>Le contexte clinique le plus fréquent de l'hyperkaliémie iatrogène est l'administration d'<strong>IEC/ARA2</strong> chez un patient en <strong>hypovolémie efficace</strong> (déshydratation extracellulaire, insuffisance cardiaque) ou présentant une <strong>insuffisance rénale chronique sous-jacente</strong>.</p>"},{"i":"e7406352fe5d","n":267,"o":"267-16","u":"Étiologies","t":"Connaître les principales étiologies des hyperkaliémies","q":"Quelles sont les causes d'hyperkaliémie par défaut d'excrétion rénale de potassium ?","a":"<p>Les causes d'hyperkaliémie par défaut d'excrétion rénale sont :</p><ul><li><strong>Insuffisance rénale aiguë</strong> (surtout si anurie).</li><li><strong>Insuffisance rénale chronique</strong> pré-terminale.</li><li><strong>Insuffisance surrénale</strong> (maladie d'Addison).</li><li><strong>Hyporéninisme-hypoaldostéronisme</strong> (néphropathie diabétique, VIH).</li><li><strong>Iatrogénie ++</strong> : <strong>IEC/ARA2</strong>, <strong>AINS</strong>, <strong>diurétiques épargneurs de K⁺</strong> (amiloride, spironolactone), <strong>anticalcineurines</strong>, <strong>héparine</strong>, <strong>cotrimoxazole</strong>.</li></ul>"},{"i":"02fcffaa5272","n":267,"o":"267-17","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hyperkaliémie sévère","q":"Expliquez l'ordre des priorités de traitement en cas de signes ECG d'hyperkaliémie menaçante.","a":"<p>En cas de signes ECG d'hyperkaliémie, l'ordre de priorité est le suivant :</p><ul><li>En premier : <strong>gluconate de calcium IV</strong> pour stabiliser la membrane cardiaque.</li><li>Ensuite : <strong>insuline + G10% + salbutamol</strong> pour le transfert intracellulaire du potassium.</li><li>Enfin : <strong>épuration du potassium</strong> (furosémide ou hémodialyse) pour éliminer l'excès de potassium du corps.</li></ul>"},{"i":"40e8de6b98f9","n":267,"o":"267-17","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hyperkaliémie sévère","q":"Quelles sont les indications justifiant un traitement d'urgence de l'hyperkaliémie ?","a":"<p>Un traitement d'urgence de l'hyperkaliémie est indiqué en présence d'une kaliémie <strong>supérieure à 6,5 mmol/L</strong> ou de <strong>signes électrocardiographiques</strong> menaçants.</p>"},{"i":"4393781cba60","n":267,"o":"267-17","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hyperkaliémie sévère","q":"Quels traitements permettent un transfert intracellulaire du potassium lors d'une hyperkaliémie sévère ?","a":"<ul><li><strong>Insuline IV + soluté glucosé à 10% (G10%)</strong> : permet de baisser la kaliémie de 0,5 à 1,2 mmol/L en 1 à 2 heures.</li><li><strong>Salbutamol en nébulisation</strong> : a un effet additif pour favoriser le transfert intracellulaire.</li></ul>"},{"i":"61e8fb906338","n":267,"o":"267-17","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hyperkaliémie sévère","q":"Quelle est la première étape du traitement d'urgence de l'hyperkaliémie et quel est son mécanisme d'action ?","a":"<p>La première étape est l'administration de <strong>gluconate de calcium IV</strong>. Son mécanisme d'action est un <strong>antagonisme membranaire</strong>, protégeant le myocarde des effets de l'hyperkaliémie. Il <strong>ne diminue pas la kaliémie</strong>.</p>"},{"i":"91fdb3c57bc5","n":267,"o":"267-17","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hyperkaliémie sévère","q":"Quelles sont les méthodes d'élimination du potassium utilisées en urgence face à une hyperkaliémie ?","a":"<ul><li>Le <strong>Furosémide</strong> : si la déplétion volémique est absente (volume extracellulaire non diminué).</li><li>L'<strong>hémodialyse</strong> : c'est la méthode la plus rapide, indiquée notamment en cas d'insuffisance rénale aiguë anurique avec hyperkaliémie menaçante sur l'ECG.</li></ul>"},{"i":"c3fd9e372b53","n":267,"o":"267-17","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hyperkaliémie sévère","q":"Quelles sont les contre-indications ou précautions particulières concernant le gluconate de calcium dans le traitement d'urgence de l'hyperkaliémie ?","a":"<p>Le gluconate de calcium est <strong>contre-indiqué chez les patients sous digitaliques</strong> (le chlorure de magnésium peut être utilisé en alternative). Il ne doit <strong>jamais être mélangé au bicarbonate</strong>.</p>"},{"i":"d1047489dc07","n":267,"o":"267-19","u":"Prise en charge","t":"Connaître le traitement de l’hyperkaliémie chronique modérée","q":"Quel est l'impact de la médication concomitante et de l'équilibre acido-basique sur la gestion de l'hyperkaliémie chronique modérée ?","a":"<p>Il est crucial de :</p><ul><li>Procéder à l'<strong>arrêt ou à l'adaptation des médicaments hyperkaliémiants</strong> (inhibiteurs de l'enzyme de conversion/antagonistes des récepteurs de l'angiotensine II, anti-inflammatoires non stéroïdiens, diurétiques épargneurs de potassium).</li><li>Corriger une <strong>acidose métabolique associée</strong>, avec un objectif de bicarbonatémie <strong>supérieur à 23 mmol/L</strong>.</li></ul>"},{"i":"e09c4c82b89c","n":267,"o":"267-19","u":"Prise en charge","t":"Connaître le traitement de l’hyperkaliémie chronique modérée","q":"Quels sont les traitements médicamenteux spécifiques de l'hyperkaliémie chronique modérée ?","a":"<p>Les traitements médicamenteux incluent :</p><ul><li>Les <strong>résines échangeuses d'ions</strong> (par exemple, le <strong>sulfonate de polystyrène sodique</strong>).</li><li>Les <strong>diurétiques hypokaliémiants</strong> tels que le <strong>furosémide</strong> ou les <strong>thiazidiques</strong>, bien que non systématiques.</li></ul>"},{"i":"e6e0be57ef9f","n":267,"o":"267-19","u":"Prise en charge","t":"Connaître le traitement de l’hyperkaliémie chronique modérée","q":"Quelle est la prise en charge initiale non urgente de l'hyperkaliémie chronique modérée, notamment dans le contexte d'une insuffisance rénale chronique ?","a":"<p>La prise en charge initiale repose sur la <strong>restriction des apports potassiques</strong>.</p><ul><li>Il faut éviter les aliments riches en potassium comme les <strong>sels de régime, les fruits secs, le chocolat et certains légumes</strong>.</li></ul>"},{"i":"2dd06f468291","n":267,"o":"267-20","u":"Définition","t":"Connaître les indications de prescription d’une kaliémie et définition de l’hypokaliémie","q":"Dans quel contexte doit-on éliminer une fausse hypokaliémie ?","a":"<p>Une fausse hypokaliémie doit être éliminée en présence d'une <strong>leucémie hyperleucocytaire</strong> si le prélèvement sanguin est laissé à température ambiante, en raison d'une <strong>captation de K⁺ par les leucocytes</strong> <em>in vitro</em>.</p>"},{"i":"2e1c8a09eb83","n":267,"o":"267-20","u":"Définition","t":"Connaître les indications de prescription d’une kaliémie et définition de l’hypokaliémie","q":"Comment définit-on l'hypokaliémie et quels sont les seuils de gravité ?","a":"<p>L'hypokaliémie est définie par une <strong>kaliémie inférieure à 3,5 mmol/L</strong>.</p><ul><li>Une hypokaliémie est considérée comme <strong>menaçante</strong> si la kaliémie est <strong>inférieure à 2,5 mmol/L</strong> ou s'il existe des <strong>signes électrocardiographiques (ECG)</strong> associés.</li></ul>"},{"i":"b4a3d0691e93","n":267,"o":"267-20","u":"Définition","t":"Connaître les indications de prescription d’une kaliémie et définition de l’hypokaliémie","q":"Quelle est la physiopathologie principale des troubles du rythme cardiaque en cas d'hypokaliémie ?","a":"<p>L'hypokaliémie augmente l'excitabilité membranaire par <strong>hyperpolarisation</strong> des cellules, favorisant ainsi l'apparition de <strong>troubles du rythme cardiaque</strong>.</p>"},{"i":"e64e1523eb77","n":267,"o":"267-20","u":"Définition","t":"Connaître les indications de prescription d’une kaliémie et définition de l’hypokaliémie","q":"Quelles sont les principales indications de dosage de la kaliémie ?","a":"<p>Le dosage de la kaliémie est demandé devant :</p><ul><li>Tout <strong>signe d'appel</strong> pouvant évoquer une hypokaliémie (notamment musculaires ou ECG).</li><li>Tout patient recevant un <strong>traitement hypokaliémiant</strong>.</li></ul>"},{"i":"7616266c44f8","n":267,"o":"267-21","u":"Diagnostic positif","t":"Connaître les symptômes cliniques de l’hypokaliémie","q":"Quelles sont les manifestations rénales chroniques de l'hypokaliémie ?","a":"<p>L'hypokaliémie, si elle est chronique, peut entraîner des manifestations rénales telles que :</p><ul><li>Un <strong>syndrome polyuro-polydipsique</strong>, lié à un <strong>diabète insipide néphrogénique</strong> acquis.</li><li>Une <strong>alcalose métabolique</strong>.</li><li>Une <strong>néphropathie interstitielle chronique</strong>.</li></ul>"},{"i":"847714e44af0","n":267,"o":"267-21","u":"Diagnostic positif","t":"Connaître les symptômes cliniques de l’hypokaliémie","q":"Quels sont les symptômes cliniques de l'hypokaliémie concernant les muscles lisses ?","a":"<p>L'hypokaliémie affecte les muscles lisses, entraînant :</p><ul><li>Une <strong>constipation</strong>.</li><li>Un <strong>iléus paralytique</strong> (ou syndrome d'Ogilvie).</li><li>Un <strong>retard de reprise du transit post-opératoire</strong>.</li></ul>"},{"i":"a3d1f408125a","n":267,"o":"267-21","u":"Diagnostic positif","t":"Connaître les symptômes cliniques de l’hypokaliémie","q":"Quels sont les symptômes cliniques principaux de l'hypokaliémie au niveau des muscles striés ?","a":"<p>L'hypokaliémie provoque au niveau des muscles striés :</p><ul><li>Des <strong>crampes</strong>.</li><li>Des <strong>myalgies</strong>.</li><li>Une <strong>faiblesse ou paralysie par accès</strong>, typiquement <strong>ascendante</strong>, débutant par les <strong>membres inférieurs</strong> puis progressant vers le tronc et le diaphragme.</li><li>Une <strong>rhabdomyolyse</strong> en cas de déplétion sévère.</li></ul>"},{"i":"0ff62add9333","n":267,"o":"267-22","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hypokaliémie","q":"Quelles sont les anomalies des intervalles et les troubles du rythme cardiaque redoutés en cas d'hypokaliémie ?","a":"<ul><li>Il y a un <strong>allongement de l'intervalle QT</strong>.</li><li>Les troubles du rythme cardiaque redoutés incluent : <ul><li>fibrillation auriculaire (FA)</li><li>extrasystoles ventriculaires (ESV)</li><li>tachycardie ventriculaire (TV)</li><li><strong>torsade de pointe (très fréquente et dangereuse)</strong></li><li>fibrillation ventriculaire (FV)</li></ul></li></ul>"},{"i":"237c3435ba42","n":267,"o":"267-22","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hypokaliémie","q":"Comment évoluent les ondes T et U sur l'ECG en cas d'hypokaliémie progressive ?","a":"<p>En cas d'hypokaliémie progressive, l'<strong>onde T s'affaisse ou s'inverse</strong>, et une <strong>onde U pathologique apparaît</strong>.</p>"},{"i":"2737e1e10500","n":267,"o":"267-22","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hypokaliémie","q":"Quels sont les facteurs aggravants des troubles du rythme induits par l'hypokaliémie ?","a":"<p>Les facteurs aggravants des troubles du rythme induits par l'hypokaliémie sont l'<strong>hypercalcémie</strong>, l'<strong>hypomagnésémie</strong> (qui favorise la torsade de pointe) et l'utilisation de <strong>digitaliques</strong>.</p>"},{"i":"32b4166f1475","n":267,"o":"267-22","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hypokaliémie","q":"Quelle est l'anomalie électrocardiographique initiale de l'hypokaliémie ?","a":"<p>L'anomalie électrocardiographique initiale de l'hypokaliémie est le <strong>sous-décalage du segment ST</strong> et l'<strong>allongement de l'intervalle PR</strong>.</p>"},{"i":"f4f09b5916e7","n":267,"o":"267-22","u":"Examens complémentaires","t":"Connaître les anomalies ECG associées à l’hypokaliémie","q":"Quel est le danger principal de l'hypokaliémie sévère lié aux troubles du rythme cardiaque ?","a":"<p>Le danger principal de l'hypokaliémie sévère est la survenue d'une <strong>torsade de pointe</strong>, potentiellement létale, particulièrement favorisée par une <strong>hypomagnésémie associée</strong>.</p>"},{"i":"0fbd7d6847a6","n":267,"o":"267-23","u":"Étiologies","t":"Connaître les principales étiologies des hypokaliémies","q":"Quelle étiologie majeure doit être systématiquement recherchée devant une hypokaliémie associée à une HTA ?","a":"<p>Devant une hypokaliémie associée à une <strong>HTA</strong>, il faut systématiquement rechercher un <strong>hyperminéralocorticisme</strong> jusqu'à preuve du contraire.</p>"},{"i":"19f4bf1e504f","n":267,"o":"267-23","u":"Étiologies","t":"Connaître les principales étiologies des hypokaliémies","q":"Quelles sont les trois causes principales d'hypokaliémie à retenir pour l'EDN ?","a":"<p>Les trois causes principales d'hypokaliémie sont :</p><ul><li>Les <strong>diarrhées</strong> (pertes digestives).</li><li>L'utilisation de <strong>diurétiques</strong> (pertes rénales).</li><li>L'<strong>alcalose</strong> (transfert intracellulaire).</li></ul>"},{"i":"4f381289b612","n":267,"o":"267-23","u":"Étiologies","t":"Connaître les principales étiologies des hypokaliémies","q":"Comment l'analyse de la kaliurèse permet-elle d'orienter le diagnostic étiologique d'une hypokaliémie ?","a":"<p>L'analyse de la kaliurèse permet d'orienter le diagnostic :</p><ul><li>Si la kaliurèse est <strong>&lt; 20 mmol/L</strong> (réponse rénale appropriée), les causes sont digestives ou liées à un transfert intracellulaire : <ul><li>Carence d'apport (ex: anorexie mentale).</li><li>Transfert intracellulaire (ex: alcalose, insuline, β-adrénergiques).</li><li>Pertes digestives (ex: diarrhée).</li></ul></li><li>Si la kaliurèse est <strong>&gt; 20 mmol/L</strong> (perte rénale), la démarche se base sur la pression artérielle et le pH : <ul><li>Si HTA : <strong>hyperminéralocorticisme</strong> (hyperaldostéronisme primaire ou secondaire, syndrome de Liddle, Cushing, prise de réglisse).</li><li>Si acidose : acidocétose, acidose tubulaire rénale (type 1 ou 2).</li><li>Si alcalose : chlorurie basse (vomissements, mucoviscidose) ou élevée (diurétiques, syndrome de Bartter, syndrome de Gitelman).</li></ul></li></ul>"},{"i":"38b4a1b28fbc","n":267,"o":"267-24","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hypokaliémie sévère","q":"Quelle est la prise en charge spécifique des complications ECG de l'hypokaliémie sévère ?","a":"<p>En cas de complication ECG de l'hypokaliémie sévère :</p><ul><li>Une <strong>torsade de pointe</strong> doit être traitée par du <strong>sulfate de magnésium</strong>.</li><li>Une <strong>bradycardie</strong> doit être traitée par de l'<strong>isoprénaline</strong>.</li></ul>"},{"i":"95bc437fd7e1","n":267,"o":"267-24","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hypokaliémie sévère","q":"Quelles sont les surveillances nécessaires lors d'une supplémentation en potassium IV pour hypokaliémie sévère ?","a":"<p>Lors d'une supplémentation en potassium IV pour hypokaliémie sévère, une <strong>surveillance ECG</strong> continue est indispensable, ainsi qu'une surveillance de la <strong>sérénité de la veine</strong>, en raison du caractère veinotoxique du KCl.</p>"},{"i":"b1ce34654f4d","n":267,"o":"267-24","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hypokaliémie sévère","q":"Quel est le principe essentiel du traitement étiologique de l'hypokaliémie sévère ?","a":"<p>Le traitement étiologique de l'hypokaliémie sévère doit toujours être associé à la supplémentation en potassium. Il comprend notamment l'<strong>arrêt des médicaments hypokaliémiants</strong> et la <strong>correction d'une éventuelle hypomagnésémie</strong> associée.</p>"},{"i":"b59375504376","n":267,"o":"267-24","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hypokaliémie sévère","q":"Quelle est l'indication du traitement d'urgence de l'hypokaliémie sévère ?","a":"<p>Le traitement d'urgence de l'hypokaliémie sévère est indiqué en cas d'hypokaliémie menaçante, c'est-à-dire lorsque la concentration plasmatique de potassium est <strong>inférieure à 2,5 mmol/L</strong> ou en présence de <strong>signes ECG</strong>.</p>"},{"i":"ca7d92dcf855","n":267,"o":"267-24","u":"Prise en charge","t":"Connaître le principe du traitement d’urgence de l’hypokaliémie sévère","q":"Quelles sont les modalités de supplémentation en potassium par voie IV en cas d'hypokaliémie sévère ?","a":"<p>En cas d'hypokaliémie sévère, la supplémentation en potassium par voie IV doit être réalisée par <strong>seringue électrique (IVSE)</strong> avec un débit maximal de <strong>1 g/h</strong>. Elle doit toujours être <strong>diluée dans du soluté salé</strong> (afin d'éviter le glucosé qui pourrait aggraver l'hypokaliémie par insulinisme réactionnel) et doit avoir pour objectif une kaliémie supérieure à 3 mmol/L. Les <strong>bolus de potassium sont proscrits</strong> en raison du risque d'arrêt cardiaque irréversible.</p>"},{"i":"171f79a0aa45","n":267,"o":"267-25","u":"Diagnostic positif","t":"Connaître les indications de la gazométrie","q":"Quelles sont les indications de la gazométrie artérielle en cas de suspicion d'insuffisance respiratoire ?","a":"<ul><li><strong>Dyspnée</strong>, notamment la <strong>dyspnée de Kussmaul</strong> suggérant une acidose métabolique.</li><li>Pathologie pulmonaire <strong>hypoxémiante</strong>.</li><li>Hypo ou <strong>hyperventilation</strong>.</li><li>Insuffisance respiratoire chronique (<strong>IRespC</strong>).</li></ul>"},{"i":"28bafa8043dd","n":267,"o":"267-25","u":"Diagnostic positif","t":"Connaître les indications de la gazométrie","q":"Quelles sont les indications types de la gazométrie selon le CUEN ?","a":"<ul><li><strong>Choc</strong>.</li><li><strong>Souffrance tissulaire</strong>.</li><li>Insuffisance respiratoire <strong>aiguë et chronique</strong>.</li><li><strong>Diabète décompensé</strong>.</li><li>Intoxications responsables d'<strong>acidose métabolique</strong>.</li></ul>"},{"i":"4c3c8ab2e121","n":267,"o":"267-25","u":"Diagnostic positif","t":"Connaître les indications de la gazométrie","q":"Dans quel contexte clinique général la gazométrie artérielle est-elle indiquée ?","a":"<p>La gazométrie artérielle est indiquée devant des signes de gravité touchant un <strong>organe vital</strong> (poumon, cœur, rein, cerveau).</p>"},{"i":"8038779dd8fe","n":267,"o":"267-25","u":"Diagnostic positif","t":"Connaître les indications de la gazométrie","q":"Quelles sont les situations d'anomalie métabolique nécessitant une gazométrie artérielle ?","a":"<ul><li>Insuffisance rénale aiguë (<strong>IRA</strong>) sévère ou <strong>oligo-anurie</strong>.</li><li>État de <strong>choc</strong> (avec hyperlactatémie).</li><li><strong>Diarrhée importante</strong>.</li><li><strong>Acidocétose diabétique</strong>.</li><li>Certaines <strong>intoxications</strong>.</li></ul>"},{"i":"48b641cce821","n":267,"o":"267-27","u":"Définition","t":"Connaître la définition d’un trouble acido-basique, de son caractère métabolique ou ventilatoire","q":"Comment définit-on une acidose ou une alcalose en termes de pH sanguin ?","a":"<p>On définit une acidose (ou acidémie) par un <strong>pH &lt; 7,38</strong>. On définit une alcalose (ou alcalémie) par un <strong>pH &gt; 7,42</strong>.</p>"},{"i":"8afb3867a4ba","n":267,"o":"267-27","u":"Définition","t":"Connaître la définition d’un trouble acido-basique, de son caractère métabolique ou ventilatoire","q":"Quel est le rôle de la formule de Winter dans l'analyse des troubles acido-basiques ?","a":"<p>La formule de Winter permet d'évaluer la compensation respiratoire attendue lors d'une <strong>acidose métabolique</strong> pour déterminer si le trouble est simple ou complexe. Elle calcule la PaCO₂ attendue = <strong>1,5 × [HCO₃⁻] + 8 ± 2</strong>.</p>"},{"i":"e5b0cc1bbd92","n":267,"o":"267-27","u":"Définition","t":"Connaître la définition d’un trouble acido-basique, de son caractère métabolique ou ventilatoire","q":"Comment détermine-t-on le caractère métabolique d'un trouble acido-basique ?","a":"<p>Un trouble acido-basique est de caractère métabolique si l'anomalie primitive concerne les <strong>bicarbonates (HCO₃⁻)</strong> :</p><ul><li>Une <strong>acidose métabolique</strong> est caractérisée par un HCO₃⁻ <strong>&lt; 22 mmol/L</strong>.</li><li>Une <strong>alcalose métabolique</strong> est caractérisée par un HCO₃⁻ <strong>&gt; 26 mmol/L</strong>.</li></ul>"},{"i":"f493e299f006","n":267,"o":"267-27","u":"Définition","t":"Connaître la définition d’un trouble acido-basique, de son caractère métabolique ou ventilatoire","q":"Comment détermine-t-on le caractère ventilatoire d'un trouble acido-basique ?","a":"<p>Un trouble acido-basique est de caractère ventilatoire (ou respiratoire) si l'anomalie primitive concerne la <strong>PCO₂</strong> :</p><ul><li>Une <strong>acidose respiratoire</strong> est caractérisée par une PCO₂ <strong>&gt; 45 mmHg</strong>.</li><li>Une <strong>alcalose respiratoire</strong> est caractérisée par une PCO₂ <strong>&lt; 35 mmHg</strong>.</li></ul>"},{"i":"010e26aafce9","n":267,"o":"267-28","u":"Identifier une urgence","t":"Connaître les anomalies cliniques graves à rechercher","q":"Quels sont les signes de gravité et les complications d'une acidose métabolique sévère ?","a":"<p>Une acidose métabolique est considérée comme sévère et constitue une urgence vitale si le <strong>pH &lt; 7,10</strong> ou les <strong>HCO₃⁻ &lt; 8 mmol/L</strong>. Les signes de gravité sont :</p><ul><li><strong>Coma</strong></li><li>Baisse du <strong>débit cardiaque</strong> et du <strong>débit tissulaire</strong></li><li><strong>Résistance aux catécholamines</strong></li><li><strong>Arythmies ventriculaires</strong></li><li><strong>Dyspnée de Kussmaul</strong></li></ul>"},{"i":"25f0145532b9","n":267,"o":"267-28","u":"Identifier une urgence","t":"Connaître les anomalies cliniques graves à rechercher","q":"Quels sont les signes de gravité et les complications d'une acidose respiratoire (hypercapnie) ?","a":"<p>Les signes de gravité d'une acidose respiratoire (hypercapnie) sont :</p><ul><li><strong>Astérixis</strong> (flapping tremor)</li><li><strong>Agitation</strong> ou <strong>confusion</strong> pouvant évoluer vers le <strong>coma hypercapnique</strong></li><li>Signes adrénergiques : <strong>sueurs</strong>, <strong>tachycardie</strong>, <strong>HTA</strong></li><li><strong>Céphalées</strong> (liées à la vasodilatation du CO₂)</li></ul>"},{"i":"794da1559c2e","n":267,"o":"267-28","u":"Identifier une urgence","t":"Connaître les anomalies cliniques graves à rechercher","q":"Quel désordre électrolytique doit-on systématiquement rechercher avec une acidose métabolique menaçante ?","a":"<p>Une <strong>hyperkaliémie menaçante</strong> accompagne fréquemment l'acidose métabolique. Il est impératif de rechercher systématiquement les <strong>signes ECG</strong> associés.</p>"},{"i":"c37b4ea72744","n":267,"o":"267-28","u":"Identifier une urgence","t":"Connaître les anomalies cliniques graves à rechercher","q":"Quels sont les signes de gravité et les complications d'une alcalose métabolique sévère ?","a":"<p>Une alcalose métabolique est considérée comme sévère si le <strong>pH &gt; 7,60</strong>, engageant le pronostic vital. Le risque majeur est l'<strong>arrêt respiratoire</strong> par hypoventilation compensatrice.</p>"},{"i":"17a8b4c6ce43","n":267,"o":"267-29","u":"Démarche diagnostique","t":"Connaître les modalités du diagnostic d’une acidose métabolique liée à une insuffisance rénale, à une diarrhée, à une acidose lactique, à une acidocétose","q":"Comment définit-on biologiquement une acidose métabolique ?","a":"<p>Une acidose métabolique est définie par un <strong>pH plasmatique &lt; 7,38</strong> et un taux de <strong>bicarbonates (HCO₃⁻) plasmatiques &lt; 22 mmol/L</strong>.</p>"},{"i":"3d79b0ba4d4c","n":267,"o":"267-29","u":"Démarche diagnostique","t":"Connaître les modalités du diagnostic d’une acidose métabolique liée à une insuffisance rénale, à une diarrhée, à une acidose lactique, à une acidocétose","q":"Quelles sont les principales étiologies d'une acidose métabolique à trou anionique plasmatique normal (hyperchlorémique) ?","a":"<p>Les principales étiologies d'une acidose métabolique à TA normal sont :</p><ul><li>Les <strong>pertes digestives de HCO₃⁻</strong>, notamment par <strong>diarrhée</strong>.</li><li>Les <strong>acidoses tubulaires rénales</strong>.</li></ul>"},{"i":"8744cfae26b8","n":267,"o":"267-29","u":"Démarche diagnostique","t":"Connaître les modalités du diagnostic d’une acidose métabolique liée à une insuffisance rénale, à une diarrhée, à une acidose lactique, à une acidocétose","q":"Quelles sont les principales étiologies d'une acidose métabolique à trou anionique plasmatique augmenté (TA > 16) ?","a":"<p>Les principales étiologies d'une acidose métabolique à TA augmenté sont :</p><ul><li>L'<strong>acidose lactique</strong> (choc, biguanides, insuffisance hépatocellulaire).</li><li>L'<strong>acidocétose</strong> (diabète, jeûne, alcool avec accumulation de <strong>β-hydroxybutyrate</strong>).</li><li>L'<strong>insuffisance rénale sévère</strong> (accumulation de sulfates, phosphates).</li><li>Les <strong>intoxications</strong> (aspirine, éthylène glycol, méthanol).</li></ul>"},{"i":"aec299df6802","n":267,"o":"267-29","u":"Démarche diagnostique","t":"Connaître les modalités du diagnostic d’une acidose métabolique liée à une insuffisance rénale, à une diarrhée, à une acidose lactique, à une acidocétose","q":"Quelle est la formule du trou anionique plasmatique (TA) et à quoi sert-il pour le diagnostic d'une acidose métabolique ?","a":"<p>La formule du trou anionique plasmatique est : <strong>TA = [Na⁺ + K⁺] − [Cl⁻ + HCO₃⁻]</strong>. Il permet d'orienter le mécanisme de l'acidose métabolique en fonction de sa valeur :</p><ul><li>Un <strong>TA augmenté (&gt; 16)</strong> suggère l'accumulation d'un anion indosé.</li><li>Un <strong>TA normal</strong> (ou hyperchlorémique) suggère une perte de bicarbonates compensée par une augmentation des chlorures.</li></ul>"},{"i":"d3c603a780cb","n":267,"o":"267-29","u":"Démarche diagnostique","t":"Connaître les modalités du diagnostic d’une acidose métabolique liée à une insuffisance rénale, à une diarrhée, à une acidose lactique, à une acidocétose","q":"Quels sont les quatre examens biologiques prioritaires à réaliser devant une acidose métabolique pour rechercher les grandes causes ?","a":"<p>Devant une acidose métabolique, les quatre examens prioritaires sont :</p><ul><li>La <strong>glycémie</strong> et la <strong>cétonémie/cétonurie</strong> (recherche d'acidocétose).</li><li>Le <strong>lactate</strong> (recherche d'acidose lactique).</li><li>La <strong>créatininémie</strong> (recherche d'insuffisance rénale).</li><li>La <strong>recherche d'une diarrhée</strong> (contexte clinique et ionogramme urinaire si nécessaire).</li></ul>"},{"i":"3caac484f743","n":267,"o":"267-3","u":"Identifier une urgence","t":"Connaître les symptômes de gravité de l’hyponatrémie","q":"Quels sont les facteurs principaux qui augmentent le risque de gravité d'une hyponatrémie ?","a":"<p>Le risque de gravité est majoré dans deux situations :</p><ul><li>La <strong>rapidité d'installation</strong> de l'hyponatrémie (hyponatrémie aiguë), ne permettant pas au cerveau de s'adapter.</li><li>Une natrémie inférieure à <strong>120 mmol/L</strong>.</li></ul>"},{"i":"4442f32abe09","n":267,"o":"267-3","u":"Identifier une urgence","t":"Connaître les symptômes de gravité de l’hyponatrémie","q":"Quels sont les symptômes évoquant une hyponatrémie modérée ?","a":"<p>Les symptômes d'une hyponatrémie modérée incluent :</p><ul><li><strong>Céphalées</strong></li><li><strong>Confusion</strong></li><li><strong>Nausées</strong> (sans vomissements)</li></ul>"},{"i":"97883cd119ec","n":267,"o":"267-3","u":"Identifier une urgence","t":"Connaître les symptômes de gravité de l’hyponatrémie","q":"Quels sont les symptômes traduisant une hyponatrémie sévère, marquant une urgence, et conduisant les patients en unité de soins intensifs ?","a":"<p>Les symptômes d'une hyponatrémie sévère, nécessitant une prise en charge en soins intensifs, sont :</p><ul><li><strong>Vomissements</strong></li><li><strong>Comitialité / Convulsions</strong></li><li><strong>Détresse cardio-respiratoire</strong></li><li><strong>Somnolence</strong></li><li><strong>Coma</strong> (score de Glasgow ≤ 8)</li><li>Ces symptômes peuvent, à terme, conduire au <strong>décès</strong>.</li></ul>"},{"i":"b75af6ca6973","n":267,"o":"267-3","u":"Identifier une urgence","t":"Connaître les symptômes de gravité de l’hyponatrémie","q":"Quel est le mécanisme physiologique principal à l'origine de la gravité des symptômes dans l'hyponatrémie ?","a":"<p>La gravité des symptômes dans l'hyponatrémie résulte du <strong>gonflement cellulaire</strong>. L'eau se déplace du secteur extracellulaire vers le secteur intracellulaire, entraînant un œdème cellulaire généralisé, notamment un <strong>œdème cérébral</strong> au sein d'une boîte crânienne inextensible, et par conséquent une <strong>HTIC (Hypertension Intracrânienne)</strong>.</p>"},{"i":"e5c05366b886","n":267,"o":"267-3","u":"Identifier une urgence","t":"Connaître les symptômes de gravité de l’hyponatrémie","q":"Quelle est la prise en charge immédiate recommandée pour une hyponatrémie symptomatique sévère ?","a":"<p>Une hyponatrémie symptomatique sévère (vomissements, convulsions, troubles de conscience) relève d'une <strong>prise en charge en unité de soins intensifs</strong> et l'administration d'un <strong>soluté de NaCl hypertonique 3%</strong>. La correction doit être initiée sans attendre, mais sans corriger l'hyponatrémie trop rapidement.</p>"},{"i":"06e737e7ef3f","n":267,"o":"267-31","u":"Étiologies","t":"Connaître les principales causes d’acidose respiratoire","q":"Quelles sont les principales causes thoraco-pulmonaires d'acidose respiratoire ?","a":"<ul><li>La <strong>BPCO sévère</strong> et l'<strong>emphysème</strong>.</li><li>Certaines <strong>pneumopathies inflammatoires avec myosite diaphragmatique</strong> (lupus, polymyosite).</li><li>La <strong>cyphoscoliose</strong>.</li><li>L'<strong>obésité</strong>.</li><li>Les <strong>atteintes pleurales</strong>.</li></ul>"},{"i":"3dbc61fdc1af","n":267,"o":"267-31","u":"Étiologies","t":"Connaître les principales causes d’acidose respiratoire","q":"Quelles sont les principales causes neuromusculaires d'acidose respiratoire ?","a":"<ul><li>Le <strong>syndrome de Guillain-Barré</strong>.</li><li>La <strong>myasthénie</strong>.</li><li>La <strong>sclérose latérale amyotrophique</strong> (SLA).</li><li>Un <strong>traumatisme médullaire supérieur à C5</strong>.</li><li>Les <strong>myopathies</strong>.</li><li>Des <strong>troubles métaboliques</strong> spécifiques comme l'hypokaliémie et l'hypophosphatémie.</li></ul>"},{"i":"43a8eef334a6","n":267,"o":"267-31","u":"Étiologies","t":"Connaître les principales causes d’acidose respiratoire","q":"Quelle est la définition de l'acidose respiratoire et ses principales caractéristiques gazométriques ?","a":"<p>L'acidose respiratoire résulte d'une <strong>hypoventilation alvéolaire</strong>. Elle associe toujours une <strong>hypoxémie</strong> et une <strong>hypercapnie</strong>. En chronique, la compensation rénale (augmentation du bicarbonate HCO₃⁻) n'est jamais totale.</p>"},{"i":"a83c49fc735c","n":267,"o":"267-31","u":"Étiologies","t":"Connaître les principales causes d’acidose respiratoire","q":"Quel est le piège diagnostique clinique majeur lors d'une acidose respiratoire liée à une pathologie neuromusculaire ?","a":"<p>Dans les pathologies neuromusculaires, les <strong>signes de détresse respiratoire sont souvent peu évidents à l'examen clinique</strong> (peu de mise en jeu visible des muscles accessoires). L'hypercapnie peut être <strong>profonde</strong> sans que le tableau clinique soit bruyant, ce qui rend le diagnostic plus difficile.</p>"},{"i":"c95b8fdcd3ce","n":267,"o":"267-31","u":"Étiologies","t":"Connaître les principales causes d’acidose respiratoire","q":"Quelles sont les principales étiologies de l'acidose respiratoire d'origine centrale ?","a":"<ul><li>Les <strong>médicaments dépresseurs respiratoires</strong> (psychotropes, morphiniques).</li><li>Les <strong>atteintes cérébrales</strong> (AVC, traumatisme, infection).</li><li>Le <strong>syndrome d'Ondine</strong>.</li><li>Le <strong>syndrome d'apnées du sommeil central</strong> (SAS central).</li></ul>"},{"i":"9bbb1b93b78a","n":267,"o":"267-34","u":"Définition","t":"Savoir dans quelles circonstances doit être prescrite une calcémie et définir l’hypocalcémie","q":"Dans quelles circonstances doit être prescrite une calcémie ?","a":"<p>La calcémie doit être prescrite devant des signes d'<strong>hyperexcitabilité neuromusculaire</strong> ou dans un contexte à risque, tel qu'une <strong>chirurgie cervicale récente</strong> ou une <strong>insuffisance rénale chronique (IRC)</strong>.</p>"},{"i":"da9c8e5cabf5","n":267,"o":"267-34","u":"Définition","t":"Savoir dans quelles circonstances doit être prescrite une calcémie et définir l’hypocalcémie","q":"Quelle est la définition biologique de l'hypocalcémie, et quelle est l'importance du calcium ionisé ?","a":"<p>L'hypocalcémie est définie biologiquement par :<ul><li>Une <strong>calcémie totale corrigée inférieure à 2,20 mmol/L</strong> (88 mg/L).</li><li>Une <strong>calcémie ionisée inférieure à 1,15 mmol/L</strong>, qui correspond à une hypocalcémie « vraie ».</li></ul>La calcémie ionisée est la <strong>seule fraction du calcium réellement régulée</strong> et doit toujours être évaluée pour confirmer une hypocalcémie.</p>"},{"i":"dc2d9157a1e3","n":267,"o":"267-34","u":"Définition","t":"Savoir dans quelles circonstances doit être prescrite une calcémie et définir l’hypocalcémie","q":"Comment distinguer une « fausse hypocalcémie » d'une « vraie hypocalcémie » ?","a":"<p>Il est crucial d'éliminer une fausse hypocalcémie avant de conclure. Cela se fait en prenant en compte le taux d'albumine, le calcium étant fortement lié aux protéines :<ul><li>Une <strong>hypoalbuminémie abaisse le calcium total</strong>, mais laisse le calcium ionisé normal. C'est une fausse hypocalcémie.</li><li>Inversement, une hyperalbuminémie peut masquer une vraie hypocalcémie.</li></ul>Pour corriger la calcémie totale en fonction de l'albuminémie, on utilise la formule : <strong>Ca corrigée = Ca total + [(40 − albuminémie en g/L) × 0,025]</strong>. Tout bilan de dyscalcémie doit idéalement inclure un <strong>dosage du calcium ionisé et/ou de l'albumine</strong>.</p>"},{"i":"246f669b7204","n":267,"o":"267-36","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques associés à l’hypocalcémie","q":"Quels sont les troubles trophiques associés à l'hypocalcémie chronique ?","a":"<ul><li>Peau et phanères secs.</li><li>Altération de l'émail dentaire.</li><li><strong>Cataracte sous-capsulaire</strong>.</li><li>Syndrome de Fahr (calcification des noyaux gris centraux avec syndrome extrapyramidal).</li></ul>"},{"i":"48ad47050831","n":267,"o":"267-36","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques associés à l’hypocalcémie","q":"Quels sont les signes cliniques graves de l'hypocalcémie ?","a":"<ul><li><strong>Laryngospasme</strong>.</li><li><strong>Bronchospasme</strong>.</li><li><strong>Spasme phrénique</strong>, pouvant entraîner un arrêt cardiorespiratoire.</li><li><strong>Comitialité</strong>, particulièrement chez l'enfant.</li></ul>"},{"i":"690856ad2827","n":267,"o":"267-36","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques associés à l’hypocalcémie","q":"Quels sont les signes cliniques de la tétanie patente au cours de l'hypocalcémie ?","a":"<ul><li><strong>Paresthésies distales</strong>.</li><li><strong>Contractures caractéristiques</strong> : <ul><li>Main d'accoucheur.</li><li>Bouche en museau de carpe.</li><li>Spasme carpo-pédal.</li></ul></li></ul>"},{"i":"99c1bb7734bd","n":267,"o":"267-36","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques associés à l’hypocalcémie","q":"Comment retrouve-t-on la tétanie latente au cours de l'hypocalcémie ?","a":"<ul><li>Signe de <strong>Chvostek</strong> (percussion du nerf facial).</li><li>Signe de <strong>Trousseau</strong> (main d'accoucheur au brassard).</li><li><strong>Hyperréflexie ostéotendineuse</strong>.</li></ul>"},{"i":"cd042dd21d82","n":267,"o":"267-36","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques associés à l’hypocalcémie","q":"Comment l'intensité des signes cliniques de l'hypocalcémie est-elle influencée par sa cinétique d'installation ?","a":"<p>L'intensité des signes cliniques de l'hypocalcémie est d'autant plus marquée que l'hypocalcémie est d'installation <strong>aiguë et profonde</strong>. Une forme progressive est mieux tolérée.</p>"},{"i":"d6e93fc91139","n":267,"o":"267-38","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires utiles au diagnostic étiologique de l’hypocalcémie","q":"Comment confirme-t-on biologiquement une hypocalcémie ?","a":"<p>La confirmation d'une hypocalcémie repose sur la mesure du <strong>calcium total</strong> ainsi que du <strong>calcium ionisé</strong>. Il est également important de doser l'<strong>albuminémie</strong> afin de corriger le calcium total si nécessaire, car une hypoalbuminémie peut masquer une normocalcémie ionisée.</p>"},{"i":"eafbf2d7a8b2","n":267,"o":"267-38","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires utiles au diagnostic étiologique de l’hypocalcémie","q":"Quels sont les examens biologiques clés pour le diagnostic étiologique d'une hypocalcémie ?","a":"<p>Le diagnostic étiologique d'une hypocalcémie repose principalement sur :</p><ul><li>Le dosage de la <strong>PTH</strong> (parathormone).</li><li>La mesure de la <strong>phosphatémie</strong>.</li><li>Le dosage de la <strong>25-OH-vitamine D</strong>.</li><li>Le dosage du <strong>calcitriol</strong> (1,25-OH-vitamine D).</li><li>La mesure de la <strong>calciurie des 24 heures</strong>.</li></ul>"},{"i":"f38b1191c96e","n":267,"o":"267-38","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires utiles au diagnostic étiologique de l’hypocalcémie","q":"Comment la PTH et la phosphatémie orientent-elles le diagnostic étiologique d'une hypocalcémie ?","a":"<p>La <strong>PTH</strong> est un élément clé d'orientation :</p><ul><li>Une <strong>PTH basse ou normale</strong> oriente vers une <strong>hypoparathyroïdie</strong>.</li><li>Une <strong>PTH élevée</strong> suggère une réaction adaptée à l'hypocalcémie, orientant vers une <strong>carence en vitamine D</strong>, une <strong>insuffisance rénale chronique (IRC)</strong>, ou une <strong>résistance à la PTH</strong>.</li></ul><p>La <strong>phosphatémie</strong> affine ensuite l'étiologie, le couple PTH-phosphatémie étant fondamental.</p>"},{"i":"fc14f370c964","n":267,"o":"267-38","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires utiles au diagnostic étiologique de l’hypocalcémie","q":"Quels examens complémentaires recherchent le retentissement d'une hypocalcémie ?","a":"<p>Le principal examen pour rechercher le retentissement d'une hypocalcémie est l'<strong>Électrocardiogramme (ECG)</strong>. Des examens comme l'EMG ou l'EEG ne sont généralement pas indispensables. Pour l'atteinte osseuse, on peut rechercher des <strong>marqueurs du remodelage osseux</strong> et réaliser une <strong>DMO</strong> (densitométrie minérale osseuse).</p>"},{"i":"39b38c05366b","n":267,"o":"267-39","u":"Étiologies","t":"Connaître les principales étiologies des hypocalcémies (arbre diagnostique)","q":"Comment l'arbre diagnostique des hypocalcémies, selon le contenu donné, doit-il être abordé en premier lieu ?","a":"<p>L'arbre diagnostique des hypocalcémies doit être abordé en premier lieu par le <strong>dosage de la PTH</strong> (Parathormone), couplée à la <strong>phosphatémie</strong>, la <strong>vitamine D</strong> et la <strong>calciurie</strong>.</p>"},{"i":"61f031f6fffb","n":267,"o":"267-39","u":"Étiologies","t":"Connaître les principales étiologies des hypocalcémies (arbre diagnostique)","q":"Quelles sont les principales étiologies des hypocalcémies avec une PTH basse ou inadaptée ?","a":"<ul><li><strong>Post-chirurgicale</strong> (thyroïde, parathyroïde, cervicale) +++</li><li><strong>Auto-immune</strong> (anticorps anti-CaSR)</li><li><strong>Infiltrative</strong> (amylose, hémochromatose, maladie de Wilson, métastases)</li><li><strong>Hypomagnésémie sévère</strong></li><li><strong>Génétique</strong> : Syndrome de DiGeorge (délétion 22q11) ++</li></ul>"},{"i":"7b01f8ad4d7f","n":267,"o":"267-39","u":"Étiologies","t":"Connaître les principales étiologies des hypocalcémies (arbre diagnostique)","q":"Quelles sont les étiologies spécifiques des hypocalcémies aiguës, souvent associées à une PTH élevée ?","a":"<ul><li><strong>Chélation du calcium</strong> : par le phosphate (rhabdomyolyse, lyse tumorale), par le citrate (transfusion massive), ou par le foscarnet.</li><li><strong>Précipitation tissulaire</strong> (pancréatite aiguë)</li><li><strong>Syndrome de l'os affamé</strong> (post-parathyroïdectomie)</li><li><strong>Alcalose respiratoire aiguë</strong> (spasmophilie)</li><li>Administration de <strong>biphosphonates</strong> ou de <strong>dénosumab</strong>.</li></ul>"},{"i":"8b3e84075cdf","n":267,"o":"267-39","u":"Étiologies","t":"Connaître les principales étiologies des hypocalcémies (arbre diagnostique)","q":"Comment différencier une hypoparathyroïdie d'une carence en vitamine D au moyen de la PTH et de la phosphatémie ?","a":"<ul><li>Une phosphatémie élevée associée à une <strong>PTH basse</strong> oriente vers une <strong>hypoparathyroïdie</strong>.</li><li>Une phosphatémie basse associée à une <strong>PTH haute</strong> oriente vers une <strong>carence en vitamine D</strong>.</li></ul>"},{"i":"ab230b284a68","n":267,"o":"267-39","u":"Étiologies","t":"Connaître les principales étiologies des hypocalcémies (arbre diagnostique)","q":"Quelles sont les principales étiologies des hypocalcémies avec une PTH élevée (réaction adaptée ou inadaptée) ?","a":"<ul><li><strong>Carence ou résistance à la vitamine D</strong> (malabsorption, cirrhose, médicaments comme les antiprotéases, anticonvulsivants, corticoïdes)</li><li><strong>IRC avancée</strong></li><li><strong>Pseudo-hypoparathyroïdie</strong> (PTH très élevée, résistance, syndrome d'Albright)</li><li><strong>Hypocalcémie hypercalciurique familiale</strong> (calciurie élevée)</li></ul>"},{"i":"0a6b9672d402","n":267,"o":"267-4","u":"Étiologies","t":"Connaître les principales étiologies des hyponatrémies","q":"Quelles sont les étiologies d'une hyponatrémie quand l'osmolalité urinaire est ≤ 100 mOsm/kg ?","a":"<p>Une Uosm ≤ 100 mOsm/kg, traduisant une dilution adaptée des apports, oriente vers un déséquilibre des seuls apports, comme :</p><ul><li>La <strong>potomanie</strong></li><li>Les <strong>buveurs de bière</strong></li><li>Le syndrome « <strong>Tea and Toast</strong> »</li></ul>"},{"i":"0ceafa7303da","n":267,"o":"267-4","u":"Étiologies","t":"Connaître les principales étiologies des hyponatrémies","q":"Quelles sont les étiologies d'une hyponatrémie hypervolémique (ou 'hypovolémie efficace') ?","a":"<p>Une hyponatrémie avec hypervolémie (hypovolémie efficace), caractérisée par un système rénine-angiotensine aldostérone (SRAA) actif ou une natriurèse basse, se rencontre dans :</p><ul><li>L'<strong>insuffisance cardiaque</strong>.</li><li>La <strong>cirrhose</strong>.</li><li>Le <strong>syndrome néphrotique</strong>.</li><li>L'<strong>insuffisance rénale chronique avancée</strong>.</li></ul>"},{"i":"0d26c450d703","n":267,"o":"267-4","u":"Étiologies","t":"Connaître les principales étiologies des hyponatrémies","q":"Quelles sont les causes d'une hyponatrémie hypovolémique (diminution du Volume Extracellulaire - VEC) ?","a":"<p>En cas de diminution du VEC, on distingue :</p><ul><li>Les pertes extra-rénales (natriurèse urinaire NaU ≤ 30 mmol/L) : <strong>digestives</strong> (vomissements, diarrhées), <strong>cutanées</strong> (brûlures, hypersudation), <strong>3<sup>e</sup> secteur</strong>.</li><li>Les pertes rénales (natriurèse urinaire NaU > 30 mmol/L) : <strong>diurétiques</strong>, <strong>insuffisance surrénale</strong>, <strong>cérébral salt wasting</strong>.</li></ul>"},{"i":"789e11b5d88e","n":267,"o":"267-4","u":"Étiologies","t":"Connaître les principales étiologies des hyponatrémies","q":"Quelles sont les principales causes de SIADH (Syndrome de Sécrétion Inappropriée d'ADH) ?","a":"<p>Les causes majeures de SIADH sont :</p><ul><li>Les atteintes du <strong>système nerveux central (SNC)</strong>.</li><li>Les <strong>pneumopathies</strong>.</li><li>Certains <strong>médicaments</strong> (carbamazépine, ISRS, émétisants).</li><li>La sécrétion ectopique (par exemple, <strong>carcinome bronchique</strong>, également appelée syndrome de Schwartz-Bartter).</li></ul>"},{"i":"ad3307680d61","n":267,"o":"267-4","u":"Étiologies","t":"Connaître les principales étiologies des hyponatrémies","q":"Quelles sont les étiologies d'une hyponatrémie euvolémique ?","a":"<p>Les principales étiologies d'une hyponatrémie euvolémique, avec une natriurèse urinaire NaU > 30 mmol/L, sont :</p><ul><li>Le <strong>SIADH</strong> (Syndrome de Sécrétion Inappropriée d'ADH), qui est le plus fréquent.</li><li>L'<strong>hypothyroïdie</strong>.</li><li>L'<strong>hypocortisolisme</strong>.</li></ul>"},{"i":"f8a1ac1dd1fe","n":267,"o":"267-4","u":"Étiologies","t":"Connaître les principales étiologies des hyponatrémies","q":"Quelle est la première étape de la démarche diagnostique étiologique devant une hyponatrémie et à quoi sert-elle ?","a":"<p>La première étape est l'évaluation de l'<strong>osmolalité urinaire (Uosm)</strong>. Elle permet de distinguer les hyponatrémies par dilution adaptée des apports (Uosm ≤ 100 mOsm/kg) de celles avec dilution inadaptée (Uosm > 100 mOsm/kg).</p>"},{"i":"1a8571f6c1c1","n":267,"o":"267-40","u":"Prise en charge","t":"Connaître les principes du traitement des hypocalcémies","q":"Quel est un objectif spécifique du traitement de l'hypocalcémie dans le contexte de l'hypoparathyroïdie ?","a":"<p>Dans l'hypoparathyroïdie, l'objectif est d'atteindre une <strong>calcémie minimale asymptomatique</strong>, et non une normocalcémie stricte, afin d'éviter le risque d'hypercalciurie, de lithiase et de néphrocalcinose.</p>"},{"i":"33fe329661a2","n":267,"o":"267-40","u":"Prise en charge","t":"Connaître les principes du traitement des hypocalcémies","q":"Quelle est la vitamine D à utiliser en cas d'hypocalcémie chronique liée à une carence en vitamine D ?","a":"<p>En cas de carence en vitamine D, on utilise la <strong>vitamine D2 (ergocalciférol) ou D3 (cholécalciférol)</strong>, associée à un apport de calcium par voie orale.</p>"},{"i":"417e9ab12fce","n":267,"o":"267-40","u":"Prise en charge","t":"Connaître les principes du traitement des hypocalcémies","q":"Quelle est la vitamine D à utiliser en cas d'hypocalcémie chronique liée à une hypoparathyroïdie ?","a":"<p>En cas d'hypoparathyroïdie, on utilise une <strong>vitamine D active (calcitriol)</strong> car il n'y a pas de PTH pour l'activer, associée à un apport de calcium.</p>"},{"i":"60f4c3f1371d","n":267,"o":"267-40","u":"Prise en charge","t":"Connaître les principes du traitement des hypocalcémies","q":"Quel est le premier principe général de prise en charge des hypocalcémies ?","a":"<p>Le premier principe est le <strong>traitement étiologique</strong>, dès qu'une cause curable est identifiée.</p>"},{"i":"c1c4a4e721c1","n":267,"o":"267-40","u":"Prise en charge","t":"Connaître les principes du traitement des hypocalcémies","q":"Quelle est la prise en charge d'une hypocalcémie aiguë symptomatique ?","a":"<p>La prise en charge comprend :</p><ul><li>Administration de <strong>gluconate ou chlorure de calcium par voie intraveineuse lente</strong>, suivie d'une perfusion.</li><li>Surveillance clinique et <strong>ECG</strong>.</li><li>Correction d'une éventuelle <strong>hypomagnésémie</strong> associée.</li><li>Suspension des médicaments allongeant l'intervalle QT.</li><li><strong>Ne jamais administrer de bicarbonate ni de phosphate avec le calcium en aigu</strong> (risque de précipitation).</li></ul>"},{"i":"f5ef63bde1a7","n":267,"o":"267-40","u":"Prise en charge","t":"Connaître les principes du traitement des hypocalcémies","q":"Quelle est la vitamine D à privilégier en cas d'hypocalcémie chronique liée à une insuffisance rénale chronique ?","a":"<p>En cas d'insuffisance rénale chronique, on privilégie une <strong>vitamine D 1-hydroxylée (1-α-OH ou calcitriol)</strong>, à condition qu'il n'y ait pas d'hyperphosphatémie.</p>"},{"i":"febf18276325","n":267,"o":"267-40","u":"Prise en charge","t":"Connaître les principes du traitement des hypocalcémies","q":"Comment est gérée l'hypocalcémie chronique par apport calcique oral ?","a":"<p>L'apport calcique oral est de <strong>carbonate de calcium</strong>, à raison de <strong>500 mg à 1,5 g par jour</strong>, à prendre <strong>en dehors des repas</strong> pour éviter la formation de sels insolubles. La posologie est limitée à <strong>moins de 500 mg par jour</strong> en cas d'insuffisance rénale chronique.</p>"},{"i":"321d528d5466","n":267,"o":"267-5","u":"Prise en charge","t":"Connaître les principes du traitement des hyponatrémies en fonction de la sévérité des symptômes","q":"Comment doit-on prendre en charge une hyponatrémie sévère (natrémie &lt; 120 mmol/L et symptomatique) ?","a":"<p>Pour une hyponatrémie sévère (&lt; 120 mmol/L et symptomatique), la prise en charge se fait en <strong>USI</strong> et utilise du <strong>NaCl hypertonique 3 %</strong> pour obtenir une augmentation initiale de la natrémie de <strong>+ 5 mmol/L</strong>. Le relais est ensuite pris par du <strong>NaCl 0,9 %</strong> jusqu'à atteindre <strong>130 mmol/L</strong>.</p>"},{"i":"4c6e8cdd4bf8","n":267,"o":"267-5","u":"Prise en charge","t":"Connaître les principes du traitement des hyponatrémies en fonction de la sévérité des symptômes","q":"Quel est le traitement spécifique de l'hyponatrémie associée à une déshydratation extracellulaire (DEC) ?","a":"<p>En cas d'hyponatrémie associée à une <strong>DEC</strong>, le traitement repose sur du <strong>NaCl isotonique 9 ‰</strong>. Ceci permet de freiner la stimulation volémique de l'ADH. L'utilisation de <strong>solutés balancés</strong> est indiquée en cas d'acidose associée.</p>"},{"i":"7e48823a2924","n":267,"o":"267-5","u":"Prise en charge","t":"Connaître les principes du traitement des hyponatrémies en fonction de la sévérité des symptômes","q":"Quelle est la double approche du traitement des hyponatrémies ?","a":"<p>Le traitement des hyponatrémies repose sur deux logiques complémentaires :</p><ul><li>Corriger en fonction de la <strong>sévérité des symptômes</strong> (degré d'urgence).</li><li>Traiter selon l'<strong>état du secteur extracellulaire</strong> (volémie).</li></ul>"},{"i":"aa88f2ffa41b","n":267,"o":"267-5","u":"Prise en charge","t":"Connaître les principes du traitement des hyponatrémies en fonction de la sévérité des symptômes","q":"Comment doit-on corriger la natrémie pour éviter le risque de myélinolyse centro-pontine ?","a":"<p>Pour éviter la <strong>myélinolyse centro-pontine</strong>, la vitesse de correction de la natrémie ne doit pas dépasser <strong>10 mmol/L / 24 heures</strong>, puis <strong>&lt; 8 mmol/L</strong> les 24 heures suivantes. Il est impératif de <strong>toujours corriger une hypokaliémie associée</strong>, car l'apport de KCl accélère la remontée de la natrémie.</p>"},{"i":"b58b6f7d8551","n":267,"o":"267-5","u":"Prise en charge","t":"Connaître les principes du traitement des hyponatrémies en fonction de la sévérité des symptômes","q":"Comment traiter une hyponatrémie euvolémique, notamment en cas de SIADH ?","a":"<p>Pour une hyponatrémie euvolémique comme celle du SIADH, le traitement initial est la <strong>restriction hydrique</strong>. Si cela est insuffisant, d'autres options incluent l'<strong>urée per os</strong> ou l'association <strong>furosémide + sel</strong>. En cas d'échec chronique, le <strong>tolvaptan</strong> (antagoniste V2 de l'ADH) peut être utilisé.</p>"},{"i":"c128bb0714ca","n":267,"o":"267-5","u":"Prise en charge","t":"Connaître les principes du traitement des hyponatrémies en fonction de la sévérité des symptômes","q":"Quelles sont les mesures générales applicables dans le traitement de toutes les hyponatrémies, indépendamment de leur cause ?","a":"<p>Dans tous les cas d'hyponatrémie, les mesures générales incluent une <strong>restriction hydrique</strong> (limitée à <strong>500 mL/j</strong>) et la limitation des solutés hypotoniques (notamment le <strong>G5 %</strong>).</p>"},{"i":"1ed5b9335984","n":267,"o":"267-6","u":"Prise en charge","t":"Connaître le principal risque de la correction rapide des hyponatrémies","q":"Quels sont les facteurs de risque de survenue d'une myélinolyse centro-pontine lors de la correction d'une hyponatrémie ?","a":"<ul><li>Une correction trop rapide de l'hyponatrémie (> <strong>10 mmol/L</strong> en 24 heures).</li><li>Une hyponatrémie <strong>chronique</strong>.</li><li>Des terrains fragiles tels que l'<strong>hypoxie</strong>, la <strong>malnutrition</strong>, l'<strong>éthylisme</strong> et l'<strong>hypokaliémie</strong>.</li></ul>"},{"i":"37902919e03e","n":267,"o":"267-6","u":"Prise en charge","t":"Connaître le principal risque de la correction rapide des hyponatrémies","q":"Quelles sont les manifestations cliniques du locked-in syndrome, symptôme de la myélinolyse centro-pontine ?","a":"<ul><li><strong>Tétraparésie spastique</strong>.</li><li><strong>Diplégie faciale</strong>.</li><li><strong>Paralysie oculomotrice</strong> (avec verticalité souvent préservée).</li><li>Il s'agit d'un syndrome de désafférentation moteur complet, mais sans trouble de la <strong>vigilance</strong>.</li></ul>"},{"i":"85c8d5dbc53a","n":267,"o":"267-6","u":"Prise en charge","t":"Connaître le principal risque de la correction rapide des hyponatrémies","q":"Quelle est la physiopathologie de la myélinolyse centro-pontine lors de la correction d'une hyponatrémie ?","a":"<p>C'est une <strong>démyélinisation osmotique</strong> résultant d'une correction trop rapide de l'hyponatrémie, en particulier si elle est chronique. La rapidité de l'augmentation de la natrémie entraîne un stress osmotique au niveau du pont.</p>"},{"i":"86cf80871f01","n":267,"o":"267-6","u":"Prise en charge","t":"Connaître le principal risque de la correction rapide des hyponatrémies","q":"Quel est l'examen radiologique de référence et ses signes en cas de myélinolyse centro-pontine ?","a":"<p>L'<strong>IRM cérébrale</strong> est l'examen de référence, montrant un <strong>hypersignal T2 FLAIR</strong> du centre du pont (protubérance).</p>"},{"i":"9fe70b6f871b","n":267,"o":"267-6","u":"Prise en charge","t":"Connaître le principal risque de la correction rapide des hyponatrémies","q":"Comment prévenir la myélinolyse centro-pontine lors de la prise en charge d'une hyponatrémie ?","a":"<ul><li>Une <strong>correction progressive</strong> de la natrémie est primordiale.</li><li>La cible est une augmentation de la natrémie de <strong>< 10 mmol/L</strong> durant les 24 premières heures, puis <strong>< 8 mmol/L</strong> les 24 heures suivantes.</li><li>En cas de correction trop rapide, il est possible de « faire machine arrière » en administrant un <strong>soluté glucosé 5 %</strong> associé à de la <strong>desmopressine</strong>.</li></ul>"},{"i":"bbf81be2d33c","n":267,"o":"267-6","u":"Prise en charge","t":"Connaître le principal risque de la correction rapide des hyponatrémies","q":"Quel est le risque principal associé à une correction rapide de l'hyponatrémie, en particulier chronique ?","a":"<p>Le risque majeur est la <strong>myélinolyse centro-pontine</strong> (également appelée démyélinisation osmotique).</p>"},{"i":"11a4581bb18d","n":267,"o":"267-7","u":"Définition","t":"Connaître les modalités du diagnostic d’une hypernatrémie","q":"En physiopathologie, que traduit une hypernatrémie et quelle en est la conséquence cellulaire ?","a":"<p>L'hypernatrémie traduit un <strong>bilan hydrique négatif</strong>. Elle entraîne une <strong>hyperosmolalité</strong> plasmatique qui cause un déplacement de l'eau hors des cellules, aboutissant à une <strong>déshydratation intracellulaire (DIC)</strong>.</p>"},{"i":"17ce431986c3","n":267,"o":"267-7","u":"Définition","t":"Connaître les modalités du diagnostic d’une hypernatrémie","q":"Quels sont les signes cliniques permettant de diagnostiquer une hypernatrémie ?","a":"<ul><li>Une <strong>soif</strong>, parfois intense, est le symptôme cardinal.</li><li>Une <strong>perte de poids</strong>.</li><li>Une <strong>sécheresse des muqueuses</strong>, notamment visible sur la face inférieure de la langue.</li><li>Un <strong>syndrome polyuro-polydipsique</strong> si la cause est rénale.</li></ul>"},{"i":"2508cef16ffc","n":267,"o":"267-7","u":"Définition","t":"Connaître les modalités du diagnostic d’une hypernatrémie","q":"Comment définir l'hypernatrémie d'après les critères biologiques ?","a":"<p>L'hypernatrémie est définie par une <strong>natrémie supérieure à 145 mmol/L</strong>, associée à une <strong>osmolalité plasmatique supérieure à 300 mOsm/kg</strong>.</p>"},{"i":"b0f9e85a545f","n":267,"o":"267-7","u":"Définition","t":"Connaître les modalités du diagnostic d’une hypernatrémie","q":"Pourquoi l'hypernatrémie est-elle considérée comme rare et dans quelles situations survient-elle le plus souvent ?","a":"<p>L'hypernatrémie est rare car la <strong>soif</strong> compense la perte d'eau. Elle survient en cas de <strong>trouble de la soif</strong> ou d'un <strong>trouble d'accès à l'eau</strong>, notamment chez le sujet âgé, le nourrisson, ou en cas de coma.</p>"},{"i":"53e400286410","n":267,"o":"267-9","u":"Identifier une urgence","t":"Connaître les symptômes de gravité de l’hypernatrémie","q":"Quels sont les signes neurologiques de gravité d'une hypernatrémie ?","a":"<p>Les signes neurologiques de gravité d'une hypernatrémie sont :</p><ul><li><strong>Fièvre d'origine centrale</strong>.</li><li><strong>Somnolence</strong>, <strong>asthénie</strong>, <strong>troubles du comportement</strong> (irritabilité).</li><li><strong>Crise convulsive</strong>, <strong>coma</strong>.</li><li><strong>Hémorragies cérébro-méningées</strong>, <strong>hématomes sous-duraux</strong>, <strong>thromboses veineuses cérébrales</strong> (liés à la rétraction du parenchyme cérébral).</li></ul>"},{"i":"541cc269ec6d","n":267,"o":"267-9","u":"Identifier une urgence","t":"Connaître les symptômes de gravité de l’hypernatrémie","q":"Quels sont les critères biologiques de gravité d'une hypernatrémie ?","a":"<p>Biologiquement, une hypernatrémie est considérée grave lorsque :</p><ul><li>La <strong>natrémie est supérieure à 145 mmol/L</strong>.</li><li>L'<strong>osmolalité plasmatique est supérieure à 300 mOsm/kg</strong>.</li></ul>"},{"i":"c5eb58c08104","n":267,"o":"267-9","u":"Identifier une urgence","t":"Connaître les symptômes de gravité de l’hypernatrémie","q":"Quelle est la complication majeure d'une correction trop rapide d'une hypernatrémie chronique ?","a":"<p>La correction trop rapide d'une hypernatrémie chronique expose à un risque d'<strong>œdème cérébral</strong>.</p>"}]};